{
  "name": "ISO-Certifieringsplattform",
  "description": "En komplett plattform för att hjälpa företag att bli certifierade enligt ISO 9001, 14001 och 45001 med AI-drivet stöd för mallar, avvikelsehantering och intern kommunikation.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type ISOStandard = '9001' | '14001' | '45001';

export interface ISOChapter {
  id: string;
  number: string;
  title: string;
  description: string;
  completed: boolean;
  standard: ISOStandard;
}

export interface Incident {
  id: string;
  type: 'deviation' | 'accident' | 'improvement';
  title: string;
  description: string;
  date: string;
  reporter: string;
  status: 'open' | 'investigating' | 'closed';
}

export interface Template {
  id: string;
  name: string;
  category: string;
  content: string;
}

export interface Message {
  id: string;
  user: string;
  text: string;
  timestamp: string;
}

export interface User {
  name: string;
  email: string;
  role: 'admin' | 'employee';
  company: string;
}

import { ISOChapter } from './types';

export const ISO_CHAPTERS: ISOChapter[] = [
  { id: '4', number: '4', title: 'Organisationens förutsättningar', description: 'Förståelse för organisationen och dess förutsättningar.', completed: false, standard: '9001' },
  { id: '5', number: '5', title: 'Ledarskap', description: 'Ledningens engagemang och ansvar.', completed: false, standard: '9001' },
  { id: '6', number: '6', title: 'Planering', description: 'Åtgärder för att hantera risker och möjligheter.', completed: false, standard: '9001' },
  { id: '7', number: '7', title: 'Stöd', description: 'Resurser, kompetens och medvetenhet.', completed: false, standard: '9001' },
  { id: '8', number: '8', title: 'Verksamhet', description: 'Planering och styrning av verksamheten.', completed: false, standard: '9001' },
  { id: '9', number: '9', title: 'Utvärdering av prestanda', description: 'Övervakning, mätning och analys.', completed: false, standard: '9001' },
  { id: '10', number: '10', title: 'Förbättring', description: 'Avvikelser, korrigerande åtgärder och ständiga förbättringar.', completed: false, standard: '9001' },
];

export const APP_NAME = "ISO Mastermind AI";

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateISOTemplate = async (topic: string, standard: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Skapa en professionell företagsmall för följande ämne inom ISO ${standard}: "${topic}". Inkludera rubriker, syfte, ansvar och en tabell för uppföljning. Svara på svenska.`,
      config: {
        temperature: 0.7,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini API error:", error);
    return "Ett fel uppstod vid generering av mallen. Kontrollera din API-nyckel.";
  }
};

export const getISOAdvice = async (chapter: string, standard: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Förklara enkelt vad som krävs för att uppfylla kapitel ${chapter} i ISO ${standard}. Ge 3 konkreta exempel på vad ett företag behöver göra. Svara på svenska.`,
      config: {
        temperature: 0.5,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini API error:", error);
    return "Kunde inte hämta råd just nu.";
  }
};

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const SYSTEM_INSTRUCTION = "Du är en världsledande expert på ISO 9001, 14001 och 45001. Din uppgift är att hjälpa företag att bli certifierade genom att ge konkreta, praktiska och lätthanterliga råd på svenska. Var professionell men pedagogisk.";

export const generateISOTemplate = async (topic: string, standard: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Skapa en professionell företagsmall för följande ämne inom ISO ${standard}: "${topic}". Inkludera rubriker, syfte, ansvar och en tabell för uppföljning. Svara på svenska. Använd Markdown för formatering.`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini API error:", error);
    return "Ett fel uppstod vid generering av mallen. Kontrollera din anslutning.";
  }
};

export const getISOAdvice = async (chapter: string, standard: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Förklara kapitel ${chapter} i ISO ${standard} och ge 3 konkreta steg för att uppfylla det. Svara på svenska.`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.5,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini API error:", error);
    return "Kunde inte hämta råd just nu.";
  }
};

export const askISOConsultant = async (query: string, history: any[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: query,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini API error:", error);
    return "Jag kunde tyvärr inte svara på det just nu.";
  }
};

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  BookOpen, 
  FileText, 
  AlertTriangle, 
  MessageSquare, 
  Settings, 
  LogOut, 
  ChevronRight, 
  CheckCircle2,
  Plus,
  Send,
  Sparkles,
  Bot,
  X,
  Loader2
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell,
  PieChart,
  Pie
} from 'recharts';
import { ISO_CHAPTERS } from './constants';
import { ISOStandard, ISOChapter, Incident, Message, User } from './types';
import { generateISOTemplate, getISOAdvice, askISOConsultant } from './services/geminiService';

// --- Sub-components ---

const SidebarItem: React.FC<{ 
  icon: React.ReactNode; 
  label: string; 
  active: boolean; 
  onClick: () => void 
}> = ({ icon, label, active, onClick }) => (
  <button
    onClick={onClick}
    className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
      active 
        ? 'bg-blue-600 text-white shadow-md' 
        : 'text-slate-600 hover:bg-slate-100'
    }`}
  >
    {icon}
    <span className="font-medium">{label}</span>
  </button>
);

const Card: React.FC<{ title: string; children: React.ReactNode; className?: string }> = ({ title, children, className }) => (
  <div className={`bg-white p-6 rounded-xl shadow-sm border border-slate-200 ${className}`}>
    <h3 className="text-lg font-semibold text-slate-800 mb-4 flex items-center justify-between">
      {title}
    </h3>
    {children}
  </div>
);

// --- Main App Component ---

export default function App() {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'standards' | 'templates' | 'incidents' | 'chat'>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [chapters, setChapters] = useState<ISOChapter[]>(ISO_CHAPTERS);
  const [selectedStandard, setSelectedStandard] = useState<ISOStandard>('9001');
  const [incidents, setIncidents] = useState<Incident[]>([]);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', user: 'System', text: 'Välkommen till ISO-portalen!', timestamp: '09:00' }
  ]);
  const [isAiConsultant, setIsAiConsultant] = useState(false);
  const [aiPanel, setAiPanel] = useState<{ isOpen: boolean; content: string; title: string }>({
    isOpen: false,
    content: '',
    title: ''
  });
  const [isLoading, setIsLoading] = useState(false);
  const [currentUser] = useState<User>({
    name: 'Johan Kvalitetsson',
    email: 'johan@foretaget.se',
    role: 'admin',
    company: 'Innovationsbolaget AB'
  });

  const getProgressData = () => {
    const total = chapters.length;
    const completed = chapters.filter(c => c.completed).length;
    return [
      { name: 'Klar', value: completed },
      { name: 'Kvar', value: total - completed }
    ];
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoggedIn(true);
  };

  const toggleChapter = (id: string) => {
    setChapters(prev => prev.map(c => c.id === id ? { ...c, completed: !c.completed } : c));
  };

  const openAiAdvice = async (chapter: ISOChapter) => {
    setIsLoading(true);
    setAiPanel({ isOpen: true, title: `AI-Expert: Kapitel ${chapter.number}`, content: 'Hämtar råd från ISO-konsulten...' });
    const advice = await getISOAdvice(chapter.number, selectedStandard);
    setAiPanel({ isOpen: true, title: `AI-Expert: ${chapter.title}`, content: advice || 'Kunde inte hämta råd.' });
    setIsLoading(false);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const input = form.message as HTMLInputElement;
    const text = input.value;
    if (!text) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      user: currentUser.name,
      text: text,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setMessages(prev => [...prev, userMsg]);
    input.value = '';

    if (isAiConsultant) {
      setIsLoading(true);
      const aiResponse = await askISOConsultant(text, []);
      const aiMsg: Message = {
        id: (Date.now() + 1).toString(),
        user: 'ISO-AI Konsult',
        text: aiResponse || 'Jag kunde inte svara på det.',
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      };
      setMessages(prev => [...prev, aiMsg]);
      setIsLoading(false);
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 px-4">
        <div className="max-w-md w-full bg-white rounded-2xl shadow-2xl p-8">
          <div className="text-center mb-8">
            <div className="inline-flex p-3 bg-blue-100 text-blue-600 rounded-xl mb-4">
              <CheckCircle2 size={32} />
            </div>
            <h1 className="text-2xl font-bold text-slate-900">ISO-Certify AI</h1>
            <p className="text-slate-500">Din väg till ISO 9001, 14001 & 45001</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">E-post</label>
              <input type="email" required className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" placeholder="namn@foretag.se" />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Lösenord</label>
              <input type="password" required className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" placeholder="••••••••" />
            </div>
            <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 rounded-lg transition-colors">
              Logga in
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 relative overflow-hidden">
      {/* AI Drawer */}
      <div className={`fixed inset-y-0 right-0 w-96 bg-white shadow-2xl transform transition-transform duration-300 z-50 border-l border-slate-200 ${aiPanel.isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold flex items-center text-indigo-600">
              <Sparkles className="mr-2" size={20} />
              {aiPanel.title}
            </h3>
            <button onClick={() => setAiPanel({ ...aiPanel, isOpen: false })} className="p-1 hover:bg-slate-100 rounded-full">
              <X size={20} />
            </button>
          </div>
          <div className="flex-1 overflow-y-auto prose prose-slate">
            <div className="bg-indigo-50 p-4 rounded-xl border border-indigo-100 text-indigo-900 text-sm leading-relaxed whitespace-pre-wrap">
              {isLoading && <Loader2 className="animate-spin mb-2" size={16} />}
              {aiPanel.content}
            </div>
          </div>
          <button 
            onClick={() => setAiPanel({ ...aiPanel, isOpen: false })}
            className="mt-6 w-full py-2 bg-indigo-600 text-white rounded-lg font-semibold hover:bg-indigo-700 transition-colors"
          >
            Jag förstår
          </button>
        </div>
      </div>

      {/* Sidebar */}
      <aside className="w-64 bg-white border-r border-slate-200 p-6 flex flex-col hidden md:flex">
        <div className="flex items-center space-x-2 mb-10 text-blue-600">
          <CheckCircle2 size={24} />
          <span className="text-xl font-bold tracking-tight text-slate-900">ISO Master</span>
        </div>

        <nav className="flex-1 space-y-2">
          <SidebarItem icon={<LayoutDashboard size={20}/>} label="Översikt" active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} />
          <SidebarItem icon={<BookOpen size={20}/>} label="Standarder" active={activeTab === 'standards'} onClick={() => setActiveTab('standards')} />
          <SidebarItem icon={<FileText size={20}/>} label="Mallar" active={activeTab === 'templates'} onClick={() => setActiveTab('templates')} />
          <SidebarItem icon={<AlertTriangle size={20}/>} label="Avvikelser" active={activeTab === 'incidents'} onClick={() => setActiveTab('incidents')} />
          <SidebarItem icon={<MessageSquare size={20}/>} label="Kommunikation" active={activeTab === 'chat'} onClick={() => setActiveTab('chat')} />
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-100">
          <button onClick={() => setIsLoggedIn(false)} className="w-full flex items-center space-x-2 text-slate-500 hover:text-red-500 transition-colors text-sm font-medium">
            <LogOut size={18} />
            <span>Logga ut</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-10 overflow-y-auto max-h-screen">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h2 className="text-2xl font-bold text-slate-900 uppercase tracking-tight">
              {activeTab === 'dashboard' && 'Företagsstatus'}
              {activeTab === 'standards' && 'Standarder & Krav'}
              {activeTab === 'templates' && 'AI-Mallar'}
              {activeTab === 'incidents' && 'Händelsehantering'}
              {activeTab === 'chat' && 'Samarbetscenter'}
            </h2>
          </div>
          <div className="flex items-center space-x-2">
             <div className="bg-gradient-to-r from-indigo-500 to-purple-600 text-white px-3 py-1 rounded-full text-xs font-bold flex items-center shadow-sm">
               <Sparkles size={12} className="mr-1" />
               AI-SUPPORT AKTIV
             </div>
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <Card title="Certifieringsstatus" className="md:col-span-2">
              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chapters}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="number" />
                    <YAxis hide />
                    <Tooltip />
                    <Bar dataKey="completed" fill="#3b82f6" radius={[4, 4, 0, 0]}>
                      {chapters.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.completed ? '#10b981' : '#e2e8f0'} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </Card>

            <Card title="AI-Analys">
              <div className="space-y-4">
                <div className="p-4 bg-blue-50 rounded-lg border border-blue-100">
                  <p className="text-xs font-bold text-blue-600 uppercase mb-1">Nästa steg</p>
                  <p className="text-sm text-slate-700">Fokusera på Kapitel 5 (Ledarskap) för att öka trovärdigheten i revisionen.</p>
                </div>
                <button 
                  onClick={() => openAiAdvice(chapters[0])}
                  className="w-full py-2 bg-slate-900 text-white rounded-lg text-sm font-bold flex items-center justify-center space-x-2"
                >
                  <Sparkles size={14} />
                  <span>Kör AI-Revision</span>
                </button>
              </div>
            </Card>
          </div>
        )}

        {activeTab === 'standards' && (
          <div className="space-y-6">
            <div className="flex space-x-2">
              {(['9001', '14001', '45001'] as ISOStandard[]).map(std => (
                <button
                  key={std}
                  onClick={() => setSelectedStandard(std)}
                  className={`px-4 py-2 rounded-lg font-semibold transition-all ${selectedStandard === std ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-slate-600 border border-slate-200'}`}
                >
                  ISO {std}
                </button>
              ))}
            </div>

            <div className="grid grid-cols-1 gap-4">
              {chapters.map((chapter) => (
                <div key={chapter.id} className="bg-white p-5 rounded-xl border border-slate-200 flex items-center justify-between hover:border-indigo-300 transition-all hover:shadow-md group">
                  <div className="flex items-center space-x-4">
                    <button 
                      onClick={() => toggleChapter(chapter.id)}
                      className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${chapter.completed ? 'bg-emerald-100 text-emerald-600 shadow-inner' : 'bg-slate-100 text-slate-400'}`}
                    >
                      {chapter.completed ? <CheckCircle2 size={24} /> : <div className="w-5 h-5 rounded-full border-2 border-slate-300"></div>}
                    </button>
                    <div>
                      <h4 className="font-bold text-slate-800">K{chapter.number}: {chapter.title}</h4>
                      <p className="text-sm text-slate-500">{chapter.description}</p>
                    </div>
                  </div>
                  <button 
                    onClick={() => openAiAdvice(chapter)}
                    className="flex items-center space-x-2 bg-indigo-50 text-indigo-600 px-4 py-2 rounded-lg hover:bg-indigo-100 text-sm font-bold transition-colors"
                  >
                    <Bot size={18} />
                    <span>Hjälp</span>
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'templates' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <Card title="Dokument-Generator">
              <p className="text-sm text-slate-500 mb-6 italic">Beskriv dokumentet du behöver för ISO {selectedStandard}.</p>
              <div className="space-y-4">
                <input 
                  id="template-prompt"
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner" 
                  placeholder="t.ex. 'Årlig miljöutredning'" 
                />
                <button 
                  disabled={isLoading}
                  onClick={async () => {
                    const el = document.getElementById('template-prompt') as HTMLInputElement;
                    if (!el.value) return;
                    setIsLoading(true);
                    const res = await generateISOTemplate(el.value, selectedStandard);
                    const output = document.getElementById('template-output');
                    if (output) output.innerText = res || '';
                    setIsLoading(false);
                  }}
                  className="w-full bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-700 hover:to-blue-700 text-white font-bold py-3 rounded-lg flex items-center justify-center space-x-2 shadow-lg disabled:opacity-50"
                >
                  {isLoading ? <Loader2 className="animate-spin" /> : <Sparkles size={20} />}
                  <span>Skapa ISO-Mall</span>
                </button>
              </div>
            </Card>
            <Card title="Förhandsgranskning">
              <div 
                id="template-output" 
                className="bg-slate-50 p-6 rounded-lg min-h-[400px] text-sm text-slate-700 whitespace-pre-wrap border border-slate-200 overflow-y-auto max-h-[500px]"
              >
                {isLoading ? "AI arbetar på din mall..." : "Väntar på indata..."}
              </div>
            </Card>
          </div>
        )}

        {activeTab === 'chat' && (
          <div className="flex flex-col h-[calc(100vh-250px)] bg-white rounded-xl border border-slate-200 overflow-hidden shadow-sm">
            <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
              <div className="flex items-center space-x-4">
                <button 
                  onClick={() => setIsAiConsultant(false)}
                  className={`px-3 py-1 rounded-md text-sm font-bold transition-colors ${!isAiConsultant ? 'bg-white shadow text-blue-600' : 'text-slate-500'}`}
                >
                  Intern Team-chatt
                </button>
                <button 
                  onClick={() => setIsAiConsultant(true)}
                  className={`px-3 py-1 rounded-md text-sm font-bold flex items-center space-x-2 transition-colors ${isAiConsultant ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500'}`}
                >
                  <Bot size={16} />
                  <span>ISO-Konsulten (AI)</span>
                </button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] bg-fixed">
              {messages.map(m => (
                <div key={m.id} className={`flex ${m.user === currentUser.name ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] p-4 rounded-2xl shadow-sm ${
                    m.user === currentUser.name 
                      ? 'bg-blue-600 text-white rounded-br-none' 
                      : m.user === 'ISO-AI Konsult' 
                        ? 'bg-indigo-50 border border-indigo-100 text-indigo-900 rounded-bl-none'
                        : 'bg-white border border-slate-100 text-slate-800 rounded-bl-none'
                  }`}>
                    <p className="text-[10px] font-bold opacity-70 mb-1 flex items-center">
                      {m.user === 'ISO-AI Konsult' && <Bot size={12} className="mr-1" />}
                      {m.user}
                    </p>
                    <p className="text-sm leading-relaxed">{m.text}</p>
                    <p className="text-[10px] opacity-70 text-right mt-2">{m.timestamp}</p>
                  </div>
                </div>
              ))}
              {isLoading && isAiConsultant && (
                <div className="flex justify-start">
                   <div className="bg-indigo-50 p-4 rounded-2xl rounded-bl-none animate-pulse flex space-x-2">
                     <div className="w-2 h-2 bg-indigo-400 rounded-full"></div>
                     <div className="w-2 h-2 bg-indigo-400 rounded-full"></div>
                     <div className="w-2 h-2 bg-indigo-400 rounded-full"></div>
                   </div>
                </div>
              )}
            </div>

            <div className="p-4 border-t border-slate-100 bg-white">
              <form onSubmit={handleSendMessage} className="flex space-x-2">
                <input 
                  name="message"
                  autoComplete="off"
                  className="flex-1 px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500 transition-all" 
                  placeholder={isAiConsultant ? "Fråga ISO-konsulten om råd..." : "Skriv till teamet..."} 
                />
                <button type="submit" className="p-3 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-all active:scale-95 shadow-lg">
                  <Send size={20} />
                </button>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

