  title: string;
  description: string;
  date: string;
  reporter: string;
  status: 'open' | 'investigating' | 'closed';
}

export interface Template {
  id: string;
  name: string;
  category: string;
  content: string;
}

export interface Message {
  id: string;
  user: string;
  text: string;
  timestamp: string;
}

export interface User {
  name: string;
  email: string;
  role: 'admin' | 'employee';
  company: string;
}

