export default function App() {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'standards' | 'templates' | 'incidents' | 'chat'>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [chapters, setChapters] = useState<ISOChapter[]>(ISO_CHAPTERS);
  const [selectedStandard, setSelectedStandard] = useState<ISOStandard>('9001');
  const [incidents, setIncidents] = useState<Incident[]>([]);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', user: 'System', text: 'Välkommen till ISO-portalen!', timestamp: '09:00' }
  ]);
  const [isAiConsultant, setIsAiConsultant] = useState(false);
  const [aiPanel, setAiPanel] = useState<{ isOpen: boolean; content: string; title: string }>({
    isOpen: false,
    content: '',
    title: ''
  });
  const [isLoading, setIsLoading] = useState(false);
  const [currentUser] = useState<User>({
    name: 'Johan Kvalitetsson',
    email: 'johan@foretaget.se',
    role: 'admin',
    company: 'Innovationsbolaget AB'
  });

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoggedIn(true);
  };

  const toggleChapterStatus = (id: string) => {
    setChapters(prev => prev.map(c => c.id === id ? { ...c, completed: !c.completed } : c));
  };

  const addDocumentToChapter = (chapterId: string, type: DocumentType) => {
    const docName = prompt(`Namnge din ${type}:`);
    if (!docName) return;

    const newDoc: LinkedDocument = {
      id: Date.now().toString(),
      name: docName,
      type: type,
      status: 'utkast',
      lastEdited: new Date().toLocaleDateString()
    };

    setChapters(prev => prev.map(c => {
      if (c.id === chapterId) {
        return { ...c, documents: [...c.documents, newDoc] };
      }
      return c;
    }));
  };

  const updateDocumentStatus = (chapterId: string, docId: string, status: DocumentStatus) => {
    setChapters(prev => prev.map(c => {
      if (c.id === chapterId) {
        return {
          ...c,
          documents: c.documents.map(d => d.id === docId ? { ...d, status } : d)
        };
      }
      return c;
    }));
  };

  const removeDocument = (chapterId: string, docId: string) => {
    if (!confirm("Vill du ta bort dokumentet?")) return;
    setChapters(prev => prev.map(c => {
      if (c.id === chapterId) {
        return { ...c, documents: c.documents.filter(d => d.id !== docId) };
      }
      return c;
    }));
  };

  const openAiAdvice = async (chapter: ISOChapter) => {
    setIsLoading(true);
    setAiPanel({ isOpen: true, title: `AI-Expert: Kapitel ${chapter.number}`, content: 'Hämtar råd från ISO-konsulten...' });
    const advice = await getISOAdvice(chapter.number, selectedStandard);
    setAiPanel({ isOpen: true, title: `AI-Expert: ${chapter.title}`, content: advice || 'Kunde inte hämta råd.' });
    setIsLoading(false);
  };

  const openAiDocSuggestions = async (chapter: ISOChapter) => {
    setIsLoading(true);
    setAiPanel({ isOpen: true, title: `AI-Förslag: Dokument för K${chapter.number}`, content: 'Analyserar kraven...' });
    const suggestions = await suggestRequiredDocuments(chapter.number, selectedStandard);
    setAiPanel({ isOpen: true, title: `Dokumentkrav: ${chapter.title}`, content: suggestions || 'Kunde inte hämta förslag.' });
    setIsLoading(false);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const input = form.message as HTMLInputElement;
    const text = input.value;
    if (!text) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      user: currentUser.name,
      text: text,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setMessages(prev => [...prev, userMsg]);
    input.value = '';

    if (isAiConsultant) {
      setIsLoading(true);
      const aiResponse = await askISOConsultant(text, []);
      const aiMsg: Message = {
        id: (Date.now() + 1).toString(),
        user: 'ISO-AI Konsult',
        text: aiResponse || 'Jag kunde inte svara på det.',
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      };
      setMessages(prev => [...prev, aiMsg]);
      setIsLoading(false);
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 px-4">
        <div className="max-w-md w-full bg-white rounded-2xl shadow-2xl p-8 text-center">
