                 </div>
              </Card>
           </div>
        )}
      </main>
    </div>
  );
}

export type ISOStandard = '9001' | '14001' | '45001';

export type DocumentType = 'rutin' | 'bilaga' | 'process' | 'instruktion';
export type DocumentStatus = 'saknas' | 'utkast' | 'godkänd';

export interface LinkedDocument {
  id: string;
  name: string;
  type: DocumentType;
  status: DocumentStatus;
  lastEdited: string;
}

export interface ISOChapter {
  id: string;
  number: string;
  title: string;
  description: string;
  completed: boolean;
  standard: ISOStandard;
  documents: LinkedDocument[];
}

export type CalendarEventType = 'revision' | 'rond' | 'möte' | 'utbildning' | 'mätning';

export interface CalendarEvent {
  id: string;
  title: string;
  month: number; // 0-11
  type: CalendarEventType;
  completed: boolean;
  description?: string;
}

export interface Incident {
  id: string;
  type: 'deviation' | 'accident' | 'improvement';
  title: string;
  description: string;
  date: string;
  reporter: string;
  status: 'open' | 'investigating' | 'closed';
}

export interface Message {
  id: string;
  user: string;
  text: string;
  timestamp: string;
}

export interface User {
  name: string;
  email: string;
  role: 'admin' | 'employee';
  company: string;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const SYSTEM_INSTRUCTION = "Du är en världsledande expert på ISO 9001, 14001 och 45001. Din uppgift är att hjälpa företag att bli certifierade genom att ge konkreta, praktiska och lätthanterliga råd på svenska. Var professionell men pedagogisk.";

export const generateISOTemplate = async (topic: string, standard: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Skapa en professionell företagsmall för följande ämne inom ISO ${standard}: "${topic}". Inkludera rubriker, syfte, ansvar och en tabell för uppföljning. Svara på svenska. Använd Markdown för formatering.`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini API error:", error);
    return "Ett fel uppstod vid generering av mallen.";
  }
};

export const suggestAnnualPlan = async (standards: string[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Skapa en årsplan (årshjul) för ett företag som ska certifieras enligt ${standards.join(', ')}. Ge förslag på minst en viktig aktivitet per månad (t.ex. skyddsrond, internrevision, ledningens genomgång, intressentanalys). Svara i JSON-format som en array av objekt med { "month": 0-11, "title": "Aktivitet", "type": "revision|rond|möte|utbildning|mätning", "description": "Kort motivering" }. Svara ENDAST med JSON.`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json"
      },
    });
    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini API error:", error);
    return null;
  }
};

export const suggestRequiredDocuments = async (chapter: string, standard: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Lista vilka specifika dokument (rutiner, processer, bilagor) som krävs eller rekommenderas för kapitel ${chapter} i ISO ${standard}. Svara kortfattat på svenska i punktform.`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.5,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini API error:", error);
    return "Kunde inte hämta förslag.";
  }
};

export const getISOAdvice = async (chapter: string, standard: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Förklara kapitel ${chapter} i ISO ${standard} och ge 3 konkreta steg för att uppfylla det. Svara på svenska.`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.5,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini API error:", error);
    return "Kunde inte hämta råd just nu.";
  }
};

export const askISOConsultant = async (query: string, history: any[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: query,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini API error:", error);
    return "Jag kunde tyvärr inte svara på det just nu.";
  }
};

