];

// --- Main App Component ---

export default function App() {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'standards' | 'templates' | 'incidents' | 'chat' | 'calendar'>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [chapters, setChapters] = useState<ISOChapter[]>(ISO_CHAPTERS);
  const [selectedStandard, setSelectedStandard] = useState<ISOStandard>('9001');
  const [incidents, setIncidents] = useState<Incident[]>([]);
  const [calendarEvents, setCalendarEvents] = useState<CalendarEvent[]>([]);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', user: 'System', text: 'Välkommen till ISO-portalen!', timestamp: '09:00' }
  ]);
  const [isAiConsultant, setIsAiConsultant] = useState(false);
  const [aiPanel, setAiPanel] = useState<{ isOpen: boolean; content: string; title: string }>({
    isOpen: false,
    content: '',
    title: ''
  });
  const [isLoading, setIsLoading] = useState(false);
  const [currentUser] = useState<User>({
    name: 'Johan Kvalitetsson',
    email: 'johan@foretaget.se',
    role: 'admin',
    company: 'Innovationsbolaget AB'
  });

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoggedIn(true);
  };

  const generateAnnualPlanWithAi = async () => {
    setIsLoading(true);
    const plan = await suggestAnnualPlan([selectedStandard]);
    if (plan && Array.isArray(plan)) {
      const newEvents: CalendarEvent[] = plan.map((item: any) => ({
        id: Math.random().toString(36).substr(2, 9),
        title: item.title,
        month: item.month,
        type: item.type as CalendarEventType,
        completed: false,
        description: item.description
      }));
      setCalendarEvents(newEvents);
    } else {
      alert("Kunde inte generera en plan just nu.");
    }
    setIsLoading(false);
  };

  const addCalendarEvent = (month: number) => {
    const title = prompt("Ange aktivitetens namn:");
    if (!title) return;
    const newEvent: CalendarEvent = {
      id: Date.now().toString(),
      title,
      month,
      type: 'revision',
      completed: false
    };
    setCalendarEvents([...calendarEvents, newEvent]);
  };

  const toggleEventStatus = (eventId: string) => {
    setCalendarEvents(prev => prev.map(e => e.id === eventId ? { ...e, completed: !e.completed } : e));
  };

  const toggleChapterStatus = (id: string) => {
    setChapters(prev => prev.map(c => c.id === id ? { ...c, completed: !c.completed } : c));
  };

  const addDocumentToChapter = (chapterId: string, type: DocumentType) => {
    const docName = prompt(`Namnge din ${type}:`);
    if (!docName) return;

    const newDoc: LinkedDocument = {
      id: Date.now().toString(),
      name: docName,
      type: type,
      status: 'utkast',
      lastEdited: new Date().toLocaleDateString()
    };

    setChapters(prev => prev.map(c => {
      if (c.id === chapterId) {
        return { ...c, documents: [...c.documents, newDoc] };
      }
      return c;
    }));
  };

  const updateDocumentStatus = (chapterId: string, docId: string, status: DocumentStatus) => {
    setChapters(prev => prev.map(c => {
      if (c.id === chapterId) {
        return {
          ...c,
          documents: c.documents.map(d => d.id === docId ? { ...d, status } : d)
        };
      }
      return c;
    }));
  };

  const removeDocument = (chapterId: string, docId: string) => {
    if (!confirm("Vill du ta bort dokumentet?")) return;
    setChapters(prev => prev.map(c => {
      if (c.id === chapterId) {
        return { ...c, documents: c.documents.filter(d => d.id !== docId) };
      }
      return c;
    }));
  };

  const openAiAdvice = async (chapter: ISOChapter) => {
    setIsLoading(true);
    setAiPanel({ isOpen: true, title: `AI-Expert: Kapitel ${chapter.number}`, content: 'Hämtar råd från ISO-konsulten...' });
    const advice = await getISOAdvice(chapter.number, selectedStandard);
    setAiPanel({ isOpen: true, title: `AI-Expert: ${chapter.title}`, content: advice || 'Kunde inte hämta råd.' });
    setIsLoading(false);
  };

  const openAiDocSuggestions = async (chapter: ISOChapter) => {
    setIsLoading(true);
    setAiPanel({ isOpen: true, title: `AI-Förslag: Dokument för K${chapter.number}`, content: 'Analyserar kraven...' });
    const suggestions = await suggestRequiredDocuments(chapter.number, selectedStandard);
    setAiPanel({ isOpen: true, title: `Dokumentkrav: ${chapter.title}`, content: suggestions || 'Kunde inte hämta förslag.' });
    setIsLoading(false);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const input = form.message as HTMLInputElement;
    const text = input.value;
    if (!text) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      user: currentUser.name,
      text: text,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setMessages(prev => [...prev, userMsg]);
    input.value = '';

    if (isAiConsultant) {
      setIsLoading(true);
      const aiResponse = await askISOConsultant(text, []);
      const aiMsg: Message = {
        id: (Date.now() + 1).toString(),
        user: 'ISO-AI Konsult',
        text: aiResponse || 'Jag kunde inte svara på det.',
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      };
      setMessages(prev => [...prev, aiMsg]);
      setIsLoading(false);
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 px-4">
        <div className="max-w-md w-full bg-white rounded-2xl shadow-2xl p-8 text-center">
           <div className="inline-flex p-3 bg-blue-100 text-blue-600 rounded-xl mb-4">
              <CheckCircle2 size={32} />
            </div>
            <h1 className="text-2xl font-bold text-slate-900">ISO-Certify AI</h1>
            <p className="text-slate-500 mb-8 font-medium italic">En smartare väg till certifiering</p>
            <form onSubmit={handleLogin} className="space-y-4 text-left">
              <input type="email" required className="w-full px-4 py-3 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500 transition-all shadow-inner" placeholder="E-postadress" />
              <input type="password" required className="w-full px-4 py-3 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500 transition-all shadow-inner" placeholder="Lösenord" />
              <button type="submit" className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 shadow-lg active:scale-95 transition-all">Logga in på portalen</button>
            </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 relative overflow-hidden">
      {/* AI Drawer */}
      <div className={`fixed inset-y-0 right-0 w-96 bg-white shadow-2xl transform transition-transform duration-300 z-50 border-l border-slate-200 ${aiPanel.isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold flex items-center text-indigo-600">
              <Sparkles className="mr-2" size={20} />
              {aiPanel.title}
            </h3>
            <button onClick={() => setAiPanel({ ...aiPanel, isOpen: false })} className="p-1 hover:bg-slate-100 rounded-full">
              <X size={20} />
            </button>
          </div>
          <div className="flex-1 overflow-y-auto prose prose-slate">
            <div className="bg-indigo-50 p-5 rounded-xl border border-indigo-100 text-indigo-900 text-sm leading-relaxed whitespace-pre-wrap font-medium">
              {isLoading && <Loader2 className="animate-spin mb-4 text-indigo-500" size={24} />}
              {aiPanel.content}
            </div>
          </div>
        </div>
      </div>

      {/* Sidebar */}
      <aside className="w-64 bg-white border-r border-slate-200 p-6 flex flex-col hidden md:flex">
        <div className="flex items-center space-x-2 mb-10 text-blue-600">
          <CheckCircle2 size={24} />
          <span className="text-xl font-bold text-slate-900 tracking-tighter">ISO Master</span>
        </div>
        <nav className="flex-1 space-y-2">
          <SidebarItem icon={<LayoutDashboard size={20}/>} label="Översikt" active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} />
          <SidebarItem icon={<CalendarIcon size={20}/>} label="Årshjul" active={activeTab === 'calendar'} onClick={() => setActiveTab('calendar')} />
          <SidebarItem icon={<BookOpen size={20}/>} label="Standarder" active={activeTab === 'standards'} onClick={() => setActiveTab('standards')} />
          <SidebarItem icon={<FileText size={20}/>} label="Dokumentmallar" active={activeTab === 'templates'} onClick={() => setActiveTab('templates')} />
          <SidebarItem icon={<AlertTriangle size={20}/>} label="Avvikelser" active={activeTab === 'incidents'} onClick={() => setActiveTab('incidents')} />
          <SidebarItem icon={<MessageSquare size={20}/>} label="Samarbete" active={activeTab === 'chat'} onClick={() => setActiveTab('chat')} />
        </nav>
        <div className="mt-auto pt-4 border-t border-slate-100">
           <button onClick={() => setIsLoggedIn(false)} className="w-full flex items-center space-x-2 text-slate-500 hover:text-red-500 py-2 text-sm font-medium transition-colors">
            <LogOut size={18} />
