  <button
    onClick={onClick}
    className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-all ${
      active 
        ? 'bg-blue-600 text-white shadow-lg' 
        : 'text-slate-600 hover:bg-slate-100'
    }`}
  >
    {icon}
    <span className="font-medium">{label}</span>
  </button>
);

const Card: React.FC<{ title: string; children: React.ReactNode; className?: string; action?: React.ReactNode }> = ({ title, children, className, action }) => (
  <div className={`bg-white p-6 rounded-xl shadow-sm border border-slate-200 ${className}`}>
    <div className="flex justify-between items-center mb-4">
      <h3 className="text-lg font-semibold text-slate-800">{title}</h3>
      {action}
    </div>
    {children}
  </div>
);

const MONTHS = [
  'Januari', 'Februari', 'Mars', 'April', 'Maj', 'Juni', 
  'Juli', 'Augusti', 'September', 'Oktober', 'November', 'December'
];

// --- Main App Component ---

export default function App() {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'standards' | 'templates' | 'incidents' | 'chat' | 'calendar'>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [chapters, setChapters] = useState<ISOChapter[]>(ISO_CHAPTERS);
  const [selectedStandard, setSelectedStandard] = useState<ISOStandard>('9001');
  const [incidents, setIncidents] = useState<Incident[]>([]);
  const [calendarEvents, setCalendarEvents] = useState<CalendarEvent[]>([]);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', user: 'System', text: 'Välkommen till portalen!', timestamp: '09:00' }
  ]);
  const [isAiConsultant, setIsAiConsultant] = useState(false);
  const [aiPanel, setAiPanel] = useState<{ isOpen: boolean; content: string; title: string }>({
    isOpen: false,
    content: '',
    title: ''
  });
  const [isLoading, setIsLoading] = useState(false);
  const [currentUser] = useState<User>({
    name: 'Johan Kvalitetsson',
    email: 'johan@foretaget.se',
    role: 'admin',
    company: 'Innovationsbolaget AB'
  });

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoggedIn(true);
  };

  const generateAnnualPlanWithAi = async () => {
    setIsLoading(true);
    const plan = await suggestAnnualPlan([selectedStandard]);
    if (plan && Array.isArray(plan)) {
      const newEvents: CalendarEvent[] = plan.map((item: any) => ({
        id: Math.random().toString(36).substr(2, 9),
        title: item.title,
        month: item.month,
        type: item.type as CalendarEventType,
        completed: false,
        description: item.description
      }));
      setCalendarEvents(newEvents);
    } else {
      alert("Kunde inte generera en plan just nu.");
    }
    setIsLoading(false);
  };

  const addCalendarEvent = (month: number) => {
    const title = prompt("Ange aktivitetens namn:");
    if (!title) return;
    const newEvent: CalendarEvent = {
      id: Date.now().toString(),
      title,
      month,
      type: 'revision',
      completed: false
    };
    setCalendarEvents([...calendarEvents, newEvent]);
  };

  const toggleEventStatus = (eventId: string) => {
    setCalendarEvents(prev => prev.map(e => e.id === eventId ? { ...e, completed: !e.completed } : e));
  };

  const toggleChapterStatus = (id: string) => {
    setChapters(prev => prev.map(c => c.id === id ? { ...c, completed: !c.completed } : c));
  };

  const addDocumentToChapter = (chapterId: string, type: DocumentType) => {
    const docName = prompt(`Namnge din ${type}:`);
    if (!docName) return;

    const newDoc: LinkedDocument = {
      id: Date.now().toString(),
      name: docName,
      type: type,
      status: 'utkast',
      lastEdited: new Date().toLocaleDateString()
    };

    setChapters(prev => prev.map(c => {
      if (c.id === chapterId) {
        return { ...c, documents: [...c.documents, newDoc] };
      }
      return c;
    }));
  };

  const updateDocumentStatus = (chapterId: string, docId: string, status: DocumentStatus) => {
    setChapters(prev => prev.map(c => {
      if (c.id === chapterId) {
        return {
          ...c,
          documents: c.documents.map(d => d.id === docId ? { ...d, status } : d)
        };
      }
      return c;
    }));
  };

  const removeDocument = (chapterId: string, docId: string) => {
    if (!confirm("Vill du ta bort dokumentet?")) return;
    setChapters(prev => prev.map(c => {
      if (c.id === chapterId) {
        return { ...c, documents: c.documents.filter(d => d.id !== docId) };
      }
      return c;
    }));
  };

  const openAiAdvice = async (chapter: ISOChapter) => {
    setIsLoading(true);
    setAiPanel({ isOpen: true, title: `AI-Expert: Kapitel ${chapter.number}`, content: 'Hämtar råd från ISO-konsulten...' });
    const advice = await getISOAdvice(chapter.number, selectedStandard);
    setAiPanel({ isOpen: true, title: `AI-Expert: ${chapter.title}`, content: advice || 'Kunde inte hämta råd.' });
    setIsLoading(false);
  };

  const openAiDocSuggestions = async (chapter: ISOChapter) => {
    setIsLoading(true);
    setAiPanel({ isOpen: true, title: `AI-Förslag: Dokument för K${chapter.number}`, content: 'Analyserar kraven...' });
    const suggestions = await suggestRequiredDocuments(chapter.number, selectedStandard);
    setAiPanel({ isOpen: true, title: `Dokumentkrav: ${chapter.title}`, content: suggestions || 'Kunde inte hämta förslag.' });
    setIsLoading(false);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const input = form.message as HTMLInputElement;
    const text = input.value;
    if (!text) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      user: currentUser.name,
      text: text,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setMessages(prev => [...prev, userMsg]);
    input.value = '';

    if (isAiConsultant) {
      setIsLoading(true);
      const aiResponse = await askISOConsultant(text, []);
      const aiMsg: Message = {
        id: (Date.now() + 1).toString(),
        user: 'ISO-AI Konsult',
        text: aiResponse || 'Jag kunde inte svara på det.',
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      };
      setMessages(prev => [...prev, aiMsg]);
      setIsLoading(false);
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 px-4">
        <div className="max-w-md w-full bg-white rounded-2xl shadow-2xl p-8 text-center">
           <div className="inline-flex p-3 bg-blue-100 text-blue-600 rounded-xl mb-4">
              <CheckCircle2 size={32} />
            </div>
            <h1 className="text-2xl font-bold text-slate-900">SafeQMS</h1>
            <p className="text-slate-500 mb-8 font-medium italic">En smartare väg till certifiering</p>
            <form onSubmit={handleLogin} className="space-y-4 text-left">
              <input type="email" required className="w-full px-4 py-3 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500 transition-all shadow-inner" placeholder="E-postadress" />
              <input type="password" required className="w-full px-4 py-3 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500 transition-all shadow-inner" placeholder="Lösenord" />
              <button type="submit" className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 shadow-lg active:scale-95 transition-all">Logga in på portalen</button>
            </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 relative overflow-hidden">
      {/* AI Drawer */}
      <div className={`fixed inset-y-0 right-0 w-96 bg-white shadow-2xl transform transition-transform duration-300 z-50 border-l border-slate-200 ${aiPanel.isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold flex items-center text-indigo-600">
              <Sparkles className="mr-2" size={20} />
              {aiPanel.title}
            </h3>
            <button onClick={() => setAiPanel({ ...aiPanel, isOpen: false })} className="p-1 hover:bg-slate-100 rounded-full">
              <X size={20} />
            </button>
          </div>
          <div className="flex-1 overflow-y-auto prose prose-slate">
            <div className="bg-indigo-50 p-5 rounded-xl border border-indigo-100 text-indigo-900 text-sm leading-relaxed whitespace-pre-wrap font-medium">
              {isLoading && <Loader2 className="animate-spin mb-4 text-indigo-500" size={24} />}
              {aiPanel.content}
            </div>
          </div>
        </div>
      </div>

      {/* Sidebar */}
      <aside className="w-64 bg-white border-r border-slate-200 p-6 flex flex-col hidden md:flex">
        <div className="flex items-center space-x-2 mb-10 text-blue-600">
          <CheckCircle2 size={24} />
          <span className="text-xl font-bold text-slate-900 tracking-tighter">SafeQMS</span>
        </div>
        <nav className="flex-1 space-y-2">
          <SidebarItem icon={<LayoutDashboard size={20}/>} label="Översikt" active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} />
          <SidebarItem icon={<CalendarIcon size={20}/>} label="Årshjul" active={activeTab === 'calendar'} onClick={() => setActiveTab('calendar')} />
          <SidebarItem icon={<BookOpen size={20}/>} label="Standarder" active={activeTab === 'standards'} onClick={() => setActiveTab('standards')} />
          <SidebarItem icon={<FileText size={20}/>} label="Dokumentmallar" active={activeTab === 'templates'} onClick={() => setActiveTab('templates')} />
          <SidebarItem icon={<AlertTriangle size={20}/>} label="Avvikelser" active={activeTab === 'incidents'} onClick={() => setActiveTab('incidents')} />
          <SidebarItem icon={<MessageSquare size={20}/>} label="Samarbete" active={activeTab === 'chat'} onClick={() => setActiveTab('chat')} />
        </nav>
        <div className="mt-auto pt-4 border-t border-slate-100">
           <button onClick={() => setIsLoggedIn(false)} className="w-full flex items-center space-x-2 text-slate-500 hover:text-red-500 py-2 text-sm font-medium transition-colors">
            <LogOut size={18} />
            <span>Logga ut</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-10 overflow-y-auto max-h-screen">
        <header className="flex justify-between items-center mb-8">
          <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase">
            {activeTab === 'dashboard' && 'Status & Analys'}
            {activeTab === 'calendar' && 'Årshjul'}
            {activeTab === 'standards' && 'Certifieringsprocess'}
            {activeTab === 'templates' && 'AI Dokumentation'}
            {activeTab === 'incidents' && 'Avvikelsehantering'}
            {activeTab === 'chat' && 'Samarbetscenter'}
          </h2>
          <div className="flex items-center space-x-4">
             <div className="bg-white border border-slate-200 px-3 py-1.5 rounded-lg text-xs font-bold text-slate-600 flex items-center shadow-sm">
                <Clock size={14} className="mr-2 text-blue-500" />
                Dagens datum: {new Date().toLocaleDateString()}
             </div>
          </div>
        </header>

        {activeTab === 'calendar' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center bg-white p-4 rounded-xl border border-slate-200">
              <div className="flex items-center space-x-4">
                <div className="p-3 bg-blue-50 text-blue-600 rounded-xl">
                  <CalendarIcon size={24} />
                </div>
                <div>
                  <h3 className="font-bold text-slate-800">Företagets Årscykel</h3>
                  <p className="text-sm text-slate-500">Planera in revisioner, ronder och möten under året.</p>
                </div>
              </div>
              <button 
                onClick={generateAnnualPlanWithAi}
                disabled={isLoading}
                className="bg-gradient-to-r from-indigo-600 to-blue-600 text-white px-6 py-2.5 rounded-xl font-bold shadow-lg hover:shadow-indigo-100 flex items-center space-x-2 transition-all active:scale-95 disabled:opacity-50"
              >
                {isLoading ? <Loader2 className="animate-spin" size={20} /> : <Sparkles size={20} />}
                <span>Generera Årsplan med AI</span>
              </button>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
              {MONTHS.map((monthName, index) => (
                <div key={monthName} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col group hover:border-blue-300 transition-all">
                  <div className="bg-slate-50 p-4 border-b border-slate-200 flex justify-between items-center">
                    <span className="font-black text-slate-400 text-xs uppercase tracking-widest">{monthName}</span>
                    <button onClick={() => addCalendarEvent(index)} className="p-1 hover:bg-white rounded-lg text-blue-600">
                      <Plus size={16} />
                    </button>
                  </div>
                  <div className="p-4 flex-1 space-y-3 min-h-[120px]">
                    {calendarEvents.filter(e => e.month === index).map(event => (
                      <div key={event.id} className={`p-2 rounded-lg border flex items-start space-x-2 ${event.completed ? 'bg-emerald-50 border-emerald-100' : 'bg-white border-slate-100'}`}>
                        <button 
                          onClick={() => toggleEventStatus(event.id)}
                          className={`mt-0.5 w-4 h-4 rounded border flex items-center justify-center transition-colors ${event.completed ? 'bg-emerald-500 border-emerald-600 text-white' : 'border-slate-300'}`}
                        >
                          {event.completed && <CheckCircle2 size={10} />}
                        </button>
                        <div className="flex-1 overflow-hidden">
                          <p className={`text-xs font-bold truncate ${event.completed ? 'text-emerald-700 line-through opacity-60' : 'text-slate-800'}`}>
                            {event.title}
                          </p>
                          {event.description && <p className="text-[10px] text-slate-400 mt-0.5 truncate">{event.description}</p>}
                          <div className="mt-1 flex space-x-1">
                             <span className={`text-[8px] font-black uppercase px-1 rounded ${
                               event.type === 'revision' ? 'bg-blue-100 text-blue-600' : 
                               event.type === 'rond' ? 'bg-amber-100 text-amber-600' : 'bg-slate-100 text-slate-500'
                             }`}>
                               {event.type}
                             </span>
                          </div>
                        </div>
                      </div>
                    ))}
                    {calendarEvents.filter(e => e.month === index).length === 0 && (
                      <div className="flex items-center justify-center h-full border border-dashed border-slate-100 rounded-xl">
                        <p className="text-[10px] text-slate-300 italic">Inga aktiviteter</p>
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
             <Card title="Certifieringsgrad" className="lg:col-span-2">
                <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chapters}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="number" />
                    <YAxis hide />
                    <Tooltip />
                    <Bar dataKey="completed" fill="#3b82f6" radius={[4, 4, 0, 0]}>
                      {chapters.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.completed ? '#10b981' : '#e2e8f0'} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
             </Card>
             <Card title="Kommande i Årshjulet">
                <div className="space-y-4">
                  {calendarEvents.filter(e => !e.completed).slice(0, 4).map(e => (
                    <div key={e.id} className="flex items-center space-x-3 p-3 bg-slate-50 rounded-xl border border-slate-100">
                      <div className="w-10 h-10 bg-white rounded-lg flex flex-col items-center justify-center border border-slate-100">
                         <span className="text-[8px] font-bold text-slate-400 uppercase">{MONTHS[e.month].slice(0, 3)}</span>
                         <span className="text-xs font-black text-blue-600">{e.month + 1}</span>
                      </div>
                      <div className="overflow-hidden">
                        <p className="text-xs font-bold text-slate-800 truncate">{e.title}</p>
                        <p className="text-[10px] text-slate-500 uppercase">{e.type}</p>
                      </div>
                    </div>
                  ))}
                  {calendarEvents.filter(e => !e.completed).length === 0 && (
                    <p className="text-center text-xs text-slate-400 py-10 italic">Inga planerade aktiviteter närmaste tiden.</p>
                  )}
                  <button onClick={() => setActiveTab('calendar')} className="w-full text-xs font-bold text-blue-600 py-2 border border-blue-100 rounded-lg hover:bg-blue-50">Gå till årshjulet</button>
                </div>
             </Card>
           </div>
        )}

        {activeTab === 'standards' && (
          <div className="space-y-8">
            <div className="flex space-x-2 bg-white p-1 rounded-xl border border-slate-200 inline-flex shadow-sm">
              {(['9001', '14001', '45001'] as ISOStandard[]).map(std => (
                <button
                  key={std}
                  onClick={() => setSelectedStandard(std)}
                  className={`px-6 py-2 rounded-lg text-sm font-black transition-all ${selectedStandard === std ? 'bg-blue-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
                >
                  ISO {std}
                </button>
              ))}
            </div>

            <div className="grid grid-cols-1 gap-6">
              {chapters.map((chapter) => (
                <div key={chapter.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden transition-all hover:border-blue-400 group">
                  <div className="p-6 flex items-start justify-between border-b border-slate-50">
                    <div className="flex items-start space-x-4">
                      <button 
                        onClick={() => toggleChapterStatus(chapter.id)}
                        className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all shadow-sm border ${chapter.completed ? 'bg-emerald-500 border-emerald-600 text-white' : 'bg-slate-50 border-slate-200 text-slate-300'}`}
                      >
                        <CheckCircle2 size={24} />
                      </button>
                      <div>
                        <div className="flex items-center space-x-2">
                          <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest">KAPITEL {chapter.number}</span>
                          {chapter.documents.length > 0 && (
                             <span className="px-2 py-0.5 bg-slate-100 text-slate-600 text-[10px] font-bold rounded uppercase">
                               {chapter.documents.length} DOKUMENT
                             </span>
                          )}
                        </div>
                        <h4 className="text-lg font-bold text-slate-800 tracking-tight">{chapter.title}</h4>
                        <p className="text-sm text-slate-500 max-w-2xl mt-1 leading-relaxed">{chapter.description}</p>
                      </div>
                    </div>
                    <div className="flex space-x-2">
                      <button 
                        onClick={() => openAiDocSuggestions(chapter)}
                        className="p-2.5 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-100 transition-colors shadow-sm"
                      >
                        <Lightbulb size={20} />
                      </button>
                      <button 
                        onClick={() => openAiAdvice(chapter)}
                        className="p-2.5 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100 transition-colors shadow-sm"
                      >
                        <Bot size={20} />
                      </button>
                    </div>
                  </div>

                  <div className="bg-slate-50/50 p-6">
                    <div className="flex justify-between items-center mb-5">
                      <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Rutiner, Processer & Bilagor</h5>
                      <div className="flex space-x-2">
                        <button onClick={() => addDocumentToChapter(chapter.id, 'rutin')} className="text-[10px] font-black bg-white border border-slate-200 px-3 py-1.5 rounded-lg hover:bg-blue-50 hover:text-blue-600 flex items-center shadow-sm">
                          <Plus size={12} className="mr-1" /> RUTIN
                        </button>
                        <button onClick={() => addDocumentToChapter(chapter.id, 'process')} className="text-[10px] font-black bg-white border border-slate-200 px-3 py-1.5 rounded-lg hover:bg-emerald-50 hover:text-emerald-600 flex items-center shadow-sm">
                          <GitBranch size={12} className="mr-1" /> PROCESS
                        </button>
                        <button onClick={() => addDocumentToChapter(chapter.id, 'bilaga')} className="text-[10px] font-black bg-white border border-slate-200 px-3 py-1.5 rounded-lg hover:bg-amber-50 hover:text-amber-600 flex items-center shadow-sm">
                          <Paperclip size={12} className="mr-1" /> BILAGA
                        </button>
                      </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                      {chapter.documents.map(doc => (
                        <div key={doc.id} className="bg-white p-3.5 rounded-xl border border-slate-100 flex items-center justify-between shadow-sm group hover:shadow-md transition-all">
                          <div className="flex items-center space-x-3 overflow-hidden">
                            <div className={`p-2 rounded-lg ${
                              doc.type === 'rutin' ? 'bg-blue-50 text-blue-600' : 
                              doc.type === 'process' ? 'bg-emerald-50 text-emerald-600' : 'bg-amber-50 text-amber-600'
                            }`}>
                              {doc.type === 'rutin' ? <FileBadge size={16} /> : 
                               doc.type === 'process' ? <GitBranch size={16} /> : <Paperclip size={16} />}
                            </div>
                            <div className="overflow-hidden text-left">
                              <p className="text-xs font-bold text-slate-800 truncate">{doc.name}</p>
                              <div className="flex items-center space-x-2 mt-0.5">
                                <select 
                                  value={doc.status}
                                  onChange={(e) => updateDocumentStatus(chapter.id, doc.id, e.target.value as DocumentStatus)}
                                  className={`text-[9px] font-black uppercase py-0.5 px-1.5 rounded border-none outline-none cursor-pointer ${
                                    doc.status === 'godkänd' ? 'bg-emerald-100 text-emerald-700' :
                                    doc.status === 'utkast' ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-500'
                                  }`}
                                >
                                  <option value="saknas">Saknas</option>
                                  <option value="utkast">Utkast</option>
                                  <option value="godkänd">Godkänd</option>
                                </select>
                              </div>
                            </div>
                          </div>
                          <button 
                            onClick={() => removeDocument(chapter.id, doc.id)}
                            className="text-slate-300 hover:text-red-500 p-1 transition-colors"
                          >
                            <Trash2 size={14} />
                          </button>
                        </div>
                      ))}
                      {chapter.documents.length === 0 && (
                        <div className="col-span-full py-6 text-center border border-dashed border-slate-200 rounded-2xl bg-white/50">
                          <p className="text-xs text-slate-400 font-medium">Inga dokument länkade. Använd AI-insikter för att se vad som behövs.</p>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'templates' && (
           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <Card title="ISO-Mall Generator">
              <p className="text-sm text-slate-500 mb-6 font-medium">Låt AI skapa grunden för dina rutiner och processer.</p>
              <div className="space-y-4">
                <div className="relative">
                  <input 
                    id="template-prompt"
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner" 
                    placeholder="Beskriv rutin, t.ex. 'Krisberedskap'" 
                  />
                  <Search className="absolute left-3 top-3.5 text-slate-400" size={18} />
                </div>
                <button 
                  disabled={isLoading}
                  onClick={async () => {
                    const el = document.getElementById('template-prompt') as HTMLInputElement;
                    if (!el.value) return;
                    setIsLoading(true);
                    const res = await generateISOTemplate(el.value, selectedStandard);
                    const output = document.getElementById('template-output');
                    if (output) output.innerText = res || '';
                    setIsLoading(false);
                  }}
                  className="w-full bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-700 hover:to-blue-700 text-white font-black py-3.5 rounded-xl flex items-center justify-center space-x-2 shadow-lg disabled:opacity-50 transition-all active:scale-[0.98]"
                >
                  {isLoading ? <Loader2 className="animate-spin" /> : <Sparkles size={20} />}
                  <span>SKAPA DOKUMENT</span>
                </button>
              </div>
            </Card>
            <Card title="Dokumentinnehåll">
              <div 
                id="template-output" 
                className="bg-slate-50 p-6 rounded-xl min-h-[400px] text-sm text-slate-700 whitespace-pre-wrap border border-slate-200 overflow-y-auto max-h-[500px] leading-relaxed font-mono"
              >
                {isLoading ? "AI:n sammanställer bästa praxis för din organisation..." : "Generera en mall för att se innehåll här."}
              </div>
            </Card>
          </div>
        )}

        {activeTab === 'chat' && (
          <div className="flex flex-col h-[calc(100vh-250px)] bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
             <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
              <div className="flex items-center space-x-3">
                <button 
                  onClick={() => setIsAiConsultant(false)}
                  className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-tighter transition-all ${!isAiConsultant ? 'bg-white shadow-sm text-blue-600 border border-slate-200' : 'text-slate-500'}`}
                >
                  Team-chatt
                </button>
                <button 
                  onClick={() => setIsAiConsultant(true)}
                  className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-tighter flex items-center space-x-2 transition-all ${isAiConsultant ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500'}`}
                >
                  <Bot size={14} />
                  <span>ISO-Konsulten (AI)</span>
                </button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/30">
              {messages.map(m => (
                <div key={m.id} className={`flex ${m.user === currentUser.name ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] p-4 rounded-2xl shadow-sm ${
                    m.user === currentUser.name 
                      ? 'bg-blue-600 text-white rounded-br-none' 
                      : m.user === 'ISO-AI Konsult' 
                        ? 'bg-indigo-600 text-white rounded-bl-none'
                        : 'bg-white border border-slate-200 text-slate-800 rounded-bl-none'
                  }`}>
                    <p className={`text-[10px] font-black uppercase mb-1 flex items-center ${m.user === currentUser.name ? 'text-blue-100' : m.user === 'ISO-AI Konsult' ? 'text-indigo-100' : 'text-slate-400'}`}>
                      {m.user === 'ISO-AI Konsult' && <Bot size={12} className="mr-1" />}
                      {m.user}
                    </p>
                    <p className="text-sm leading-relaxed">{m.text}</p>
                    <p className={`text-[9px] font-bold text-right mt-2 ${m.user === currentUser.name ? 'text-blue-200' : 'text-slate-400'}`}>{m.timestamp}</p>
                  </div>
                </div>
              ))}
            </div>

            <div className="p-4 border-t border-slate-100 bg-white">
              <form onSubmit={handleSendMessage} className="flex space-x-2">
                <input 
                  name="message"
                  autoComplete="off"
                  className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-500 transition-all font-medium text-sm" 
                  placeholder={isAiConsultant ? "Fråga om lagkrav, dokumentation eller revision..." : "Skriv till teammedlemmar..."} 
                />
                <button type="submit" className="p-3.5 bg-blue-600 text-white rounded-2xl hover:bg-blue-700 shadow-lg active:scale-95 transition-all">
                  <Send size={22} />
                </button>
              </form>
            </div>
          </div>
        )}

        {activeTab === 'incidents' && (
           <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <button onClick={() => setIncidents(prev => [{
                    id: Date.now().toString(),
                    type: 'deviation',
                    title: 'Ny avvikelse',
                    description: 'Beskrivning saknas...',
                    date: new Date().toLocaleDateString(),
                    reporter: currentUser.name,
                    status: 'open'
                  }, ...prev])} className="p-8 bg-amber-500 text-white rounded-3xl flex items-center justify-between shadow-xl shadow-amber-100 group transition-all active:scale-95">
                    <div className="text-left">
                       <h4 className="font-black text-xl">Rapportera Avvikelse</h4>
                       <p className="text-xs font-bold opacity-80 uppercase tracking-widest mt-1">Kvalitet & Miljö</p>
                    </div>
                    <AlertTriangle size={40} className="group-hover:rotate-12 transition-transform" />
                 </button>
                 <button onClick={() => setIncidents(prev => [{
                    id: Date.now().toString(),
                    type: 'accident',
                    title: 'Ny olycka/tillbud',
                    description: 'Beskrivning saknas...',
                    date: new Date().toLocaleDateString(),
                    reporter: currentUser.name,
                    status: 'open'
                  }, ...prev])} className="p-8 bg-red-600 text-white rounded-3xl flex items-center justify-between shadow-xl shadow-red-100 group transition-all active:scale-95">
                    <div className="text-left">
                       <h4 className="font-black text-xl">Rapportera Olycka</h4>
                       <p className="text-xs font-bold opacity-80 uppercase tracking-widest mt-1">Arbetsmiljö & Säkerhet</p>
                    </div>
                    <AlertTriangle size={40} className="group-hover:rotate-12 transition-transform" />
                 </button>
              </div>
              <Card title="Händelselogg & Ärendehantering">
                 <div className="space-y-4">
                   {incidents.map(inc => (
                      <div key={inc.id} className="p-5 border border-slate-100 rounded-2xl bg-slate-50 flex items-center justify-between shadow-sm">
                         <div className="flex items-center space-x-4">
                            <div className={`p-3 rounded-xl ${inc.type === 'accident' ? 'bg-red-100 text-red-600' : 'bg-amber-100 text-amber-600'}`}>
                               <AlertTriangle size={24} />
                            </div>
                            <div>
                               <span className={`text-[10px] font-black uppercase px-2 py-0.5 rounded-md ${inc.type === 'accident' ? 'bg-red-600 text-white' : 'bg-amber-600 text-white'}`}>{inc.type === 'accident' ? 'Kritisk Olycka' : 'Avvikelse'}</span>
                               <h5 className="font-bold mt-1 text-slate-800">{inc.title}</h5>
                               <p className="text-xs text-slate-500 font-medium">{inc.description}</p>
                            </div>
                         </div>
                         <div className="text-right">
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{inc.date}</p>
                            <div className="flex items-center justify-end mt-1">
                               <span className="w-2 h-2 bg-blue-500 rounded-full mr-2"></span>
                               <p className="text-xs text-blue-600 font-black uppercase">Under utredning</p>
                            </div>
                         </div>
                      </div>
                   ))}
                   {incidents.length === 0 && <div className="text-center py-16 text-slate-300 border border-dashed border-slate-200 rounded-3xl">
                      <p className="font-bold italic">Inga registrerade händelser i systemet.</p>
                   </div>}
                 </div>
              </Card>
           </div>
        )}
      </main>
    </div>
  );
}

export type ISOStandard = '9001' | '14001' | '45001';

export type DocumentType = 'rutin' | 'bilaga' | 'process' | 'instruktion';
export type DocumentStatus = 'saknas' | 'utkast' | 'godkänd';

export interface LinkedDocument {
  id: string;
  name: string;
  type: DocumentType;
  status: DocumentStatus;
  lastEdited: string;
}

export interface ISOChapter {
  id: string;
  number: string;
  title: string;
  description: string;
  completed: boolean;
  standard: ISOStandard;
  documents: LinkedDocument[];
}

export type CalendarEventType = 'revision' | 'rond' | 'möte' | 'utbildning' | 'mätning';

export interface CalendarEvent {
  id: string;
  title: string;
  month: number; // 0-11
  type: CalendarEventType;
  completed: boolean;
  description?: string;
}

export interface Incident {
  id: string;
  type: 'deviation' | 'accident' | 'improvement';
  title: string;
  description: string;
  date: string;
  reporter: string;
  status: 'open' | 'investigating' | 'closed';
}

export interface LawRequirement {
  id: string;
  title: string;
  category: string;
  status: 'efterlevs' | 'delvis' | 'brist';
  lastReview: string;
}

export interface Objective {
  id: string;
  title: string;
  target: string;
  progress: number;
  deadline: string;
}

export interface Aspect {
  id: string;
  activity: string;
  impact: string;
  significance: 'låg' | 'medel' | 'hög';
}

export interface Message {
  id: string;
  user: string;
  text: string;
  timestamp: string;
}

export interface User {
  name: string;
  email: string;
  role: 'admin' | 'employee';
  company: string;
}

import React, { useState } from 'react';
import { 
