);

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'Maj', 'Jun', 'Jul', 'Aug', 'Sep', 'Okt', 'Nov', 'Dec'];

type Tab = 'dashboard' | 'calendar' | 'standards' | 'templates' | 'incidents' | 'rondering' | 'objectives' | 'laws' | 'aspects' | 'chat';

export default function App() {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [chapters, setChapters] = useState<ISOChapter[]>(ISO_CHAPTERS);
  const [selectedStandard, setSelectedStandard] = useState<ISOStandard>('9001');
  const [incidents, setIncidents] = useState<Incident[]>([]);
  const [calendarEvents, setCalendarEvents] = useState<CalendarEvent[]>([]);
  const [laws] = useState<LawRequirement[]>([
    { id: '1', title: 'Miljöbalken (1998:808)', category: 'Miljö', status: 'efterlevs', lastReview: '2024-01-15' },
    { id: '2', title: 'Arbetsmiljölagen (1977:1160)', category: 'Arbetsmiljö', status: 'delvis', lastReview: '2024-02-10' }
  ]);
  const [objectives] = useState<Objective[]>([
    { id: '1', title: 'Minska energiförbrukning', target: '10% sänkning', progress: 45, deadline: '2024-12-31' },
    { id: '2', title: 'Noll olycksfall', target: '0 incidenter', progress: 100, deadline: '2024-12-31' }
  ]);
  const [aspects] = useState<Aspect[]>([
    { id: '1', activity: 'Transporter', impact: 'Utsläpp av växthusgaser', significance: 'hög' },
    { id: '2', activity: 'Kontorsdrift', impact: 'Resursförbrukning', significance: 'låg' }
  ]);
  const [messages, setMessages] = useState<Message[]>([{ id: '1', user: 'System', text: 'Välkommen till SafeQMS!', timestamp: '09:00' }]);
  const [isAiConsultant, setIsAiConsultant] = useState(false);
  const [aiPanel, setAiPanel] = useState({ isOpen: false, content: '', title: '' });
  const [isLoading, setIsLoading] = useState(false);
  const [currentUser] = useState<User>({ name: 'Johan Kvalitetsson', email: 'johan@foretaget.se', role: 'admin', company: 'Innovationsbolaget AB' });

  const handleLogin = (e: React.FormEvent) => { e.preventDefault(); setIsLoggedIn(true); };

  const generatePlan = async () => {
    setIsLoading(true);
    const plan = await suggestAnnualPlan([selectedStandard]);
    if (plan) setCalendarEvents(plan.map((i: any) => ({ ...i, id: Math.random().toString(), completed: false })));
    setIsLoading(false);
  };

  const openAiAdvice = async (chapter: ISOChapter) => {
    setIsLoading(true);
    setAiPanel({ isOpen: true, title: `AI: K${chapter.number}`, content: 'Hämtar råd...' });
    const advice = await getISOAdvice(chapter.number, selectedStandard);
    setAiPanel({ isOpen: true, title: `AI-Expert: ${chapter.title}`, content: advice || 'Error.' });
    setIsLoading(false);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const input = form.message as HTMLInputElement;
    if (!input.value) return;
    const msg = { id: Date.now().toString(), user: currentUser.name, text: input.value, timestamp: 'Nu' };
    setMessages(prev => [...prev, msg]);
    const val = input.value;
    input.value = '';
    if (isAiConsultant) {
      setIsLoading(true);
      const res = await askISOConsultant(val, []);
      setMessages(prev => [...prev, { id: 'ai', user: 'ISO-AI Konsult', text: res || '...', timestamp: 'Nu' }]);
      setIsLoading(false);
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 px-4">
        <div className="max-w-md w-full bg-white rounded-3xl shadow-2xl p-10 text-center">
            <div className="inline-flex p-4 bg-blue-100 text-blue-600 rounded-2xl mb-6"><CheckCircle2 size={40} /></div>
            <h1 className="text-3xl font-black text-slate-900 tracking-tighter mb-2">SafeQMS</h1>
            <p className="text-slate-500 mb-8 font-medium">Digitalt ledningssystem med AI-stöd</p>
            <form onSubmit={handleLogin} className="space-y-4 text-left">
              <input type="email" required className="w-full px-5 py-3.5 border rounded-2xl outline-none focus:ring-2 focus:ring-blue-500" placeholder="Användarnamn" />
              <input type="password" required className="w-full px-5 py-3.5 border rounded-2xl outline-none focus:ring-2 focus:ring-blue-500" placeholder="Lösenord" />
              <button type="submit" className="w-full bg-blue-600 text-white font-bold py-4 rounded-2xl hover:bg-blue-700 shadow-xl transition-all active:scale-95">Logga in</button>
            </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50">
      <aside className="w-64 bg-white border-r border-slate-200 p-6 flex flex-col hidden lg:flex">
        <div className="flex items-center space-x-2 mb-10 text-blue-600">
          <CheckCircle2 size={28} />
          <span className="text-2xl font-black text-slate-900 tracking-tighter">SafeQMS</span>
        </div>
        <nav className="flex-1 space-y-1 overflow-y-auto pr-2">
          <SidebarItem icon={<LayoutDashboard size={18}/>} label="Översikt" active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} />
          <SidebarItem icon={<CalendarIcon size={18}/>} label="Kalender" active={activeTab === 'calendar'} onClick={() => setActiveTab('calendar')} />
          <SidebarItem icon={<BookOpen size={18}/>} label="Standarder" active={activeTab === 'standards'} onClick={() => setActiveTab('standards')} />
          <SidebarItem icon={<ClipboardList size={18}/>} label="Rondering" active={activeTab === 'rondering'} onClick={() => setActiveTab('rondering')} />
          <SidebarItem icon={<Target size={18}/>} label="Mål & Mätetal" active={activeTab === 'objectives'} onClick={() => setActiveTab('objectives')} />
          <SidebarItem icon={<AlertTriangle size={18}/>} label="Ärenden" active={activeTab === 'incidents'} onClick={() => setActiveTab('incidents')} />
          <SidebarItem icon={<Gavel size={18}/>} label="Lagar & Krav" active={activeTab === 'laws'} onClick={() => setActiveTab('laws')} />
          <SidebarItem icon={<ShieldAlert size={18}/>} label="Aspekter" active={activeTab === 'aspects'} onClick={() => setActiveTab('aspects')} />
          <SidebarItem icon={<FileText size={18}/>} label="Mallar" active={activeTab === 'templates'} onClick={() => setActiveTab('templates')} />
          <SidebarItem icon={<MessageSquare size={18}/>} label="Chatt" active={activeTab === 'chat'} onClick={() => setActiveTab('chat')} />
        </nav>
        <button onClick={() => setIsLoggedIn(false)} className="mt-6 flex items-center space-x-2 text-slate-400 hover:text-red-500 py-2 text-sm font-bold transition-colors">
          <LogOut size={18} /><span>Logga ut</span>
        </button>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto max-h-screen">
        <header className="flex justify-between items-center mb-8">
          <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">{activeTab}</h2>
          <div className="flex items-center space-x-4">
             <div className="bg-indigo-600 text-white px-4 py-2 rounded-2xl text-xs font-black flex items-center shadow-md shadow-indigo-100">
               <Sparkles size={14} className="mr-2" /> AI KONSULT AKTIV
             </div>
          </div>
        </header>

        {activeTab === 'dashboard' && (
           <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
             <Card title="Certifieringsgrad" className="lg:col-span-2">
                <div className="h-64"><ResponsiveContainer width="100%" height="100%"><BarChart data={chapters}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="number" /><YAxis hide /><Tooltip /><Bar dataKey="completed" fill="#3b82f6" radius={[4, 4, 0, 0]}>{chapters.map((e, i) => (<Cell key={i} fill={e.completed ? '#10b981' : '#e2e8f0'} />))}</Bar></BarChart></ResponsiveContainer></div>
             </Card>
             <Card title="Snabba Aktiviteter">
                <div className="space-y-4">
                   <div className="p-4 bg-amber-50 rounded-2xl border border-amber-100"><p className="text-xs font-black text-amber-600 uppercase mb-1">Kritiskt</p><p className="text-sm font-bold">2 Lagar kräver granskning</p></div>
                   <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100"><p className="text-xs font-black text-blue-600 uppercase mb-1">Mål</p><p className="text-sm font-bold">Energimål: 45% uppnått</p></div>
                </div>
             </Card>
           </div>
        )}

        {activeTab === 'calendar' && (
          <div className="space-y-6">
            <Card title="Årshjul" action={<button onClick={generatePlan} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2"><Sparkles size={16}/>AI Årsplan</button>}>
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
                {MONTHS.map((m, i) => (
                  <div key={m} className="bg-slate-50 p-4 rounded-2xl border border-slate-200 min-h-[120px]">
                    <p className="text-[10px] font-black uppercase text-slate-400 mb-2">{m}</p>
                    {calendarEvents.filter(e => e.month === i).map(e => (
                      <div key={e.id} className="text-[10px] font-bold bg-white p-2 rounded-lg border mb-1 flex justify-between">{e.title} <CheckCircle2 size={10} className={e.completed ? "text-emerald-500" : "text-slate-200"}/></div>
                    ))}
                  </div>
                ))}
              </div>
            </Card>
          </div>
        )}

        {activeTab === 'rondering' && (
           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <Card title="Aktiva Ronder" action={<button className="text-blue-600 font-bold text-sm">+ Starta Rond</button>}>
                 <div className="space-y-3">
                    <div className="p-4 border rounded-2xl flex justify-between items-center"><div className="font-bold">Månadsrond Produktion</div><span className="text-xs bg-emerald-100 text-emerald-700 px-2 py-1 rounded">Klar</span></div>
                    <div className="p-4 border rounded-2xl flex justify-between items-center"><div className="font-bold">Skyddsrond Kontor</div><span className="text-xs bg-amber-100 text-amber-700 px-2 py-1 rounded">Pågående</span></div>
                 </div>
              </Card>
              <Card title="AI Checklistor">
                 <p className="text-sm text-slate-500 mb-4">Låt AI skapa en checklist för din specifika verksamhet.</p>
                 <input className="w-full p-3 bg-slate-50 border rounded-xl mb-3" placeholder="t.ex. 'Livsmedelssäkerhet i storkök'" />
                 <button className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold">Skapa checklist med AI</button>
              </Card>
           </div>
        )}

        {activeTab === 'objectives' && (
           <Card title="Mål & KPI:er">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 {objectives.map(o => (
                   <div key={o.id} className="p-6 border rounded-3xl bg-slate-50">
                      <h4 className="font-black text-slate-800 mb-2 uppercase text-sm tracking-tight">{o.title}</h4>
                      <div className="flex justify-between text-xs font-bold mb-2"><span>Status: {o.progress}%</span><span>Mål: {o.target}</span></div>
                      <div className="w-full bg-slate-200 h-3 rounded-full overflow-hidden"><div className="bg-blue-600 h-full" style={{width: `${o.progress}%`}}></div></div>
                      <p className="text-[10px] text-slate-400 mt-3">Deadline: {o.deadline}</p>
                   </div>
                 ))}
              </div>
           </Card>
        )}

        {activeTab === 'laws' && (
           <Card title="Laglista">
              <div className="overflow-hidden border rounded-2xl">
                 <table className="w-full text-left">
