               <button onClick={() => setIsAiConsultant(false)} className={`px-4 py-2 rounded-xl text-xs font-black uppercase ${!isAiConsultant ? 'bg-white shadow-sm text-blue-600 border' : 'text-slate-400'}`}>Team</button>
               <button onClick={() => setIsAiConsultant(true)} className={`px-4 py-2 rounded-xl text-xs font-black uppercase flex items-center gap-2 ${isAiConsultant ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400'}`}><Bot size={14}/>AI Konsult</button>
