                      <p className="text-sm">{m.text}</p>
                    </div>
                  </div>
                ))}
             </div>
             <form onSubmit={handleSendMessage} className="p-4 border-t flex gap-2"><input name="message" className="flex-1 p-4 bg-slate-50 rounded-2xl outline-none" placeholder="Skriv meddelande..." /><button className="bg-blue-600 text-white p-4 rounded-2xl shadow-lg"><Send size={24}/></button></form>
          </div>
        )}
      </main>

      <div className={`fixed inset-y-0 right-0 w-96 bg-white shadow-2xl transition-transform duration-300 z-50 border-l ${aiPanel.isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-8 h-full flex flex-col">
          <div className="flex justify-between items-center mb-8"><h3 className="font-black text-indigo-600 flex items-center gap-2"><Sparkles size={20}/>AI EXPERT</h3><button onClick={() => setAiPanel({...aiPanel, isOpen: false})}><X/></button></div>
          <div className="flex-1 overflow-y-auto font-medium text-sm leading-relaxed text-slate-700 whitespace-pre-wrap bg-indigo-50 p-6 rounded-3xl border border-indigo-100">{isLoading && <Loader2 className="animate-spin mb-4"/>}{aiPanel.content}</div>
        </div>
      </div>
    </div>
  );
}

