  const [chapters, setChapters] = useState<ISOChapter[]>(ISO_CHAPTERS);
  const [selectedStandard, setSelectedStandard] = useState<ISOStandard>('9001');
  const [incidents] = useState<Incident[]>([]);
  const [calendarEvents, setCalendarEvents] = useState<CalendarEvent[]>([]);

  // Nya tillstånd för certifieringssäkring
  const [stakeholders] = useState<Stakeholder[]>([
    { id: '1', name: 'Kunder', requirements: 'Hög leveransprecision, felfria produkter', influence: 'hög' },
    { id: '2', name: 'Länsstyrelsen', requirements: 'Miljörapportering, utsläppskontroll', influence: 'hög' }
  ]);
  const [risks] = useState<RiskItem[]>([
    { id: '1', category: 'Operationell', description: 'Maskinhaveri i produktion', probability: 2, impact: 4, mitigation: 'Förebyggande underhållsschema' },
    { id: '2', category: 'Personal', description: 'Hög personalomsättning', probability: 3, impact: 3, mitigation: 'Förbättrade förmåner & arbetsmiljö' }
  ]);
  const [competence] = useState<CompetenceRecord[]>([
    { id: '1', employee: 'Anna Andersson', role: 'Produktionschef', training: [{ name: 'ISO 9001 Grund', status: 'klar' }, { name: 'HLR', status: 'klar' }] },
    { id: '2', employee: 'Erik Ek', role: 'Operatör', training: [{ name: 'Maskinsäkerhet', status: 'saknas' }] }
  ]);

  const [messages, setMessages] = useState<Message[]>([{ id: '1', user: 'System', text: 'Välkommen till SafeQMS!', timestamp: '09:00' }]);
  const [isAiConsultant, setIsAiConsultant] = useState(false);
  const [aiPanel, setAiPanel] = useState({ isOpen: false, content: '', title: '' });
  const [isLoading, setIsLoading] = useState(false);
  const [currentUser] = useState<User>({ name: 'Johan Kvalitetsson', email: 'johan@foretaget.se', role: 'admin', company: 'Innovationsbolaget AB' });

  const handleLogin = (e: React.FormEvent) => { e.preventDefault(); setIsLoggedIn(true); };

  const generatePlan = async () => {
    setIsLoading(true);
    const plan = await suggestAnnualPlan([selectedStandard]);
    if (plan) setCalendarEvents(plan.map((i: any) => ({ ...i, id: Math.random().toString(), completed: false })));
    setIsLoading(false);
  };

  const openAiAdvice = async (chapter: ISOChapter) => {
    setIsLoading(true);
    setAiPanel({ isOpen: true, title: `AI: K${chapter.number}`, content: 'Hämtar råd...' });
    const advice = await getISOAdvice(chapter.number, selectedStandard);
    setAiPanel({ isOpen: true, title: `AI-Expert: ${chapter.title}`, content: advice || 'Error.' });
    setIsLoading(false);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const input = form.message as HTMLInputElement;
    if (!input.value) return;
    const msg = { id: Date.now().toString(), user: currentUser.name, text: input.value, timestamp: 'Nu' };
    setMessages(prev => [...prev, msg]);
    const val = input.value;
    input.value = '';
    if (isAiConsultant) {
      setIsLoading(true);
      const res = await askISOConsultant(val, []);
      setMessages(prev => [...prev, { id: 'ai', user: 'ISO-AI Konsult', text: res || '...', timestamp: 'Nu' }]);
      setIsLoading(false);
    }
  };

