              <input type="password" required className="w-full px-5 py-3.5 border rounded-2xl outline-none focus:ring-2 focus:ring-blue-500" placeholder="Lösenord" />
              <button type="submit" className="w-full bg-blue-600 text-white font-bold py-4 rounded-2xl hover:bg-blue-700 shadow-xl transition-all active:scale-95">Logga in</button>
            </form>
        </div>
      </div>
    );
