        <nav className="flex-1 space-y-0.5 overflow-y-auto pr-1">
          <SidebarItem icon={<LayoutDashboard size={16}/>} label="Översikt" active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} />
