          <SidebarItem icon={<ShieldAlert size={16}/>} label="Miljöaspekter" active={activeTab === 'aspects'} onClick={() => setActiveTab('aspects')} />

          <div className="pt-4 pb-1 px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Verktyg</div>
          <SidebarItem icon={<FileText size={16}/>} label="AI Dokumentmallar" active={activeTab === 'templates'} onClick={() => setActiveTab('templates')} />
          <SidebarItem icon={<MessageSquare size={16}/>} label="Chatt & Support" active={activeTab === 'chat'} onClick={() => setActiveTab('chat')} />
