                <div className="h-64"><ResponsiveContainer width="100%" height="100%"><BarChart data={chapters}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="number" /><YAxis hide /><Tooltip /><Bar dataKey="completed" fill="#3b82f6" radius={[4, 4, 0, 0]}>{chapters.map((e, i) => (<Cell key={i} fill={e.completed ? '#10b981' : '#e2e8f0'} />))}</Bar></BarChart></ResponsiveContainer></div>
             </Card>
             <Card title="Kritiska Åtgärder">
                <div className="space-y-3">
                   <div className="p-4 bg-red-50 rounded-2xl border border-red-100 flex items-center justify-between">
                     <div><p className="text-[10px] font-black text-red-600 uppercase">Personal</p><p className="text-xs font-bold">1 Saknad maskinutbildning</p></div>
                     <ShieldAlert size={16} className="text-red-600" />
                   </div>
                   <div className="p-4 bg-amber-50 rounded-2xl border border-amber-100 flex items-center justify-between">
                     <div><p className="text-[10px] font-black text-amber-600 uppercase">Risker</p><p className="text-xs font-bold">2 Ej åtgärdade hög-risker</p></div>
                     <AlertTriangle size={16} className="text-amber-600" />
