              <Card 
                title="Mina Uppdrag (Att åtgärda)" 
                action={<span className="bg-red-500 text-white px-2 py-0.5 rounded-full text-[10px] font-black uppercase">{myIncidents.length} AKTIVA</span>}
              >
                <div className="space-y-4">
                  {myIncidents.map(inc => (
                    <div key={inc.id} className="p-4 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-between hover:bg-white hover:shadow-md transition-all group cursor-pointer">
                      <div className="flex items-center gap-4">
                         <div className={`p-3 rounded-xl ${inc.type === 'deviation' ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'}`}>
                            {inc.type === 'deviation' ? <ShieldAlert size={20}/> : <Lightbulb size={20}/>}
                         </div>
                         <div>
                            <p className="font-bold text-sm text-slate-800">{inc.title}</p>
                            <div className="flex items-center gap-3 mt-1">
                               <span className="text-[10px] font-black uppercase text-slate-400 flex items-center gap-1">
                                 <CalendarIcon size={12}/> Deadline: {inc.deadline}
                               </span>
                               <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded ${inc.status === 'investigating' ? 'bg-amber-100 text-amber-700' : 'bg-blue-100 text-blue-700'}`}>
                                 {inc.status}
                               </span>
                            </div>
                         </div>
                      </div>
                      <button className="p-2 text-slate-300 group-hover:text-blue-600 transition-colors"><ChevronRight size={20}/></button>
                    </div>
                  ))}
                  {myIncidents.length === 0 && (
                    <div className="text-center py-8">
                       <p className="text-xs text-slate-400 italic">Du har inga öppna uppdrag.</p>
                    </div>
                  )}
                </div>
              </Card>

              {/* MINA ANSVAR (DOKUMENT & PROCESSER) */}
              <Card 
                title="Mina Ansvar (Dokument & Processer)"
                action={<button className="text-blue-600 font-bold text-xs hover:underline">+ Skapa nytt</button>}
              >
                <div className="space-y-4">
                  {/* Dokument användaren äger */}
                  <div className="space-y-2">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Länkade dokument ({myDocuments.length})</p>
                    {myDocuments.map(doc => (
                      <div key={doc.id} className="p-3 bg-white border border-slate-200 rounded-xl flex items-center justify-between hover:border-blue-400 transition-all cursor-pointer">
                        <div className="flex items-center gap-3">
                           <FileBadge size={16} className="text-blue-600" />
                           <div>
                             <p className="text-xs font-bold text-slate-800">{doc.name}</p>
                             <p className="text-[9px] text-slate-400 uppercase font-black">Senast ändrad: {doc.lastEdited}</p>
                           </div>
                        </div>
                        <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded border ${doc.status === 'godkänd' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>
                          {doc.status}
                        </span>
                      </div>
                    ))}
                  </div>

                  {/* Processer användaren äger */}
                  <div className="space-y-2 pt-2 border-t border-slate-100">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Ägda processer ({myOwnedProcesses.length})</p>
                    <div className="flex flex-wrap gap-2">
                       {myOwnedProcesses.map(p => (
                         <div key={p.id} className="px-3 py-1.5 bg-blue-50 border border-blue-100 rounded-lg text-[10px] font-black text-blue-700 flex items-center gap-2">
                           <GitBranch size={12}/> {p.name}
                         </div>
                       ))}
                    </div>
                  </div>
                </div>
              </Card>

            </div>

            {/* Certifieringsstatus & Mål (Mindre nu) */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              <Card title="Certifieringsstatus" className="lg:col-span-2">
                <div className="h-48"><ResponsiveContainer width="100%" height="100%"><BarChart data={chapters}><XAxis dataKey="number" hide /><Tooltip /><Bar dataKey="completed" fill="#3b82f6" radius={[4, 4, 0, 0]}>{chapters.map((e, i) => (<Cell key={i} fill={e.completed ? '#10b981' : '#e2e8f0'} />))}</Bar></BarChart></ResponsiveContainer></div>
              </Card>
              <Card title="Händelser & Mål">
                 <div className="space-y-4">
                    <div className="flex items-center justify-between p-3 bg-blue-50 rounded-xl border border-blue-100">
                      <span className="text-[10px] font-black text-blue-700 uppercase">Energimål 2024</span>
                      <span className="text-xs font-bold">45% klar</span>
                    </div>
                    <div className="flex items-center justify-between p-3 bg-emerald-50 rounded-xl border border-emerald-100">
                      <span className="text-[10px] font-black text-emerald-700 uppercase">Internrevisioner</span>
                      <span className="text-xs font-bold">2/3 utförda</span>
                    </div>
                 </div>
              </Card>
            </div>
          </div>
        )}

        {/* MODAL FÖR UNDERPROCESSER */}
        {selectedProcess && (
          <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
             <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in duration-200">
               <div className={`p-6 flex justify-between items-center text-white ${
                 selectedProcess.category === 'management' ? 'bg-yellow-500' : 
                 selectedProcess.category === 'main' ? 'bg-blue-500' : 'bg-emerald-500'
               }`}>
                 <div>
                   <p className="text-[10px] font-black uppercase opacity-80 tracking-widest">Processnivå 2</p>
                   <h4 className="text-xl font-black uppercase tracking-tight">{currentSelectedProc?.name}</h4>
                   <p className="text-[10px] font-black mt-1 bg-white/20 inline-block px-2 py-0.5 rounded">Ägare: {currentSelectedProc?.owner}</p>
                 </div>
                 <button onClick={() => setSelectedProcess(null)} className="p-2 hover:bg-black/10 rounded-full transition-colors"><X size={24}/></button>
               </div>

               <div className="p-8">
                  <div className="flex justify-between items-center mb-6">
                    <h5 className="text-sm font-black text-slate-800 uppercase tracking-tight">Underprocesser & Rutiner</h5>
                    <button 
                      onClick={() => addSubProcess(selectedProcess.category, selectedProcess.id)}
                      className="flex items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-black hover:bg-slate-800 transition-all active:scale-95"
                    >
                      <Plus size={16}/> SKAPA NY
                    </button>
                  </div>

                  <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2">
                    {currentSelectedProc?.subProcesses?.map(sp => (
                      <div key={sp.id} className="group flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100 hover:border-blue-200 hover:bg-white transition-all shadow-sm">
                        <div className="flex items-center gap-4">
                           <div className="p-2 bg-white rounded-lg border shadow-sm text-blue-600"><GitBranch size={16}/></div>
                           <span className="font-bold text-sm text-slate-800">{sp.name}</span>
                        </div>
                        <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                           <button className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><FileText size={16}/></button>
                           <button onClick={() => deleteSubProcess(selectedProcess.category, selectedProcess.id, sp.id)} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"><Trash2 size={16}/></button>
                        </div>
                      </div>
                    ))}
                    {(!currentSelectedProc?.subProcesses || currentSelectedProc.subProcesses.length === 0) && (
                      <div className="text-center py-12 border-2 border-dashed border-slate-200 rounded-3xl bg-slate-50/50">
                         <p className="text-sm text-slate-400 font-bold italic">Inga underprocesser länkade ännu.</p>
                         <button onClick={() => addSubProcess(selectedProcess.category, selectedProcess.id)} className="text-xs text-blue-600 font-black mt-2 uppercase tracking-widest hover:underline">Skapa första nu</button>
                      </div>
                    )}
                  </div>
               </div>
               <div className="p-6 bg-slate-50 border-t flex justify-end gap-3">
                  <button className="text-xs font-black text-slate-400 uppercase tracking-widest px-4 py-2 hover:text-slate-600" onClick={() => setSelectedProcess(null)}>Stäng</button>
               </div>
             </div>
          </div>
        )}

        {/* ... övriga tabbar behålls ... */}
        {activeTab === 'calendar' && (
          <div className="space-y-6">
            <Card title="Årshjul" action={<button onClick={generatePlan} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold flex gap-2"><Sparkles size={14}/>AI Årsplan</button>}>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                {MONTHS.map((m, i) => (
                  <div key={m} className="bg-white p-4 rounded-2xl border border-slate-100 min-h-[140px] shadow-sm">
                    <p className="text-[10px] font-black uppercase text-slate-400 border-b pb-2 mb-2 tracking-widest">{m}</p>
                    {calendarEvents.filter(e => e.month === i).map(e => (
                      <div key={e.id} className="text-[9px] font-bold bg-slate-50 p-2 rounded-lg border border-slate-100 mb-1">{e.title}</div>
                    ))}
                  </div>
                ))}
              </div>
            </Card>
          </div>
        )}
      </main>

      {/* AI Panel Right */}
      <div className={`fixed inset-y-0 right-0 w-96 bg-white shadow-2xl transition-transform duration-300 z-50 border-l ${aiPanel.isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-8 h-full flex flex-col">
          <div className="flex justify-between items-center mb-8"><h3 className="font-black text-indigo-600 flex items-center gap-2 text-lg uppercase tracking-tighter"><Sparkles size={20}/>AI ISO-KONSULT</h3><button onClick={() => setAiPanel({...aiPanel, isOpen: false})} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><X/></button></div>
          <div className="flex-1 overflow-y-auto font-medium text-xs leading-relaxed text-slate-700 whitespace-pre-wrap bg-indigo-50 p-6 rounded-3xl border border-indigo-100 shadow-inner">
            {isLoading && <Loader2 className="animate-spin mb-4 text-indigo-600" size={24}/>}
            {aiPanel.content}
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { 
  LayoutDashboard, 
  BookOpen, 
  FileText, 
  AlertTriangle, 
  MessageSquare, 
  LogOut, 
  CheckCircle2,
  Plus,
  Send,
  Sparkles,
  Bot,
  X,
  Loader2,
  Calendar as CalendarIcon,
  Search,
  ClipboardList,
  Target,
  Gavel,
  ShieldAlert,
  Users,
  ShieldCheck,
  GraduationCap,
  ArrowRight,
  Edit2,
  ChevronRight,
  ChevronDown,
  Trash2,
  GitBranch,
  UserCheck,
  FileBadge,
  // Added Lightbulb to fix reference error on line 405
  Lightbulb
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell
} from 'recharts';
import { ISO_CHAPTERS } from './constants';
import { 
  ISOStandard, 
  ISOChapter, 
  Incident, 
  Message, 
  User, 
  LinkedDocument, 
  DocumentType, 
  DocumentStatus,
  CalendarEvent,
  CalendarEventType,
  LawRequirement,
  Objective,
  Aspect,
  Stakeholder,
  RiskItem,
  CompetenceRecord,
  ProcessItem,
  ProcessMap
} from './types';
import { 
  generateISOTemplate, 
  getISOAdvice, 
  askISOConsultant, 
  suggestRequiredDocuments,
  suggestAnnualPlan
} from './services/geminiService';

// --- Sub-components ---

const SidebarItem: React.FC<{ 
  icon: React.ReactNode; 
  label: string; 
  active: boolean; 
  onClick: () => void 
}> = ({ icon, label, active, onClick }) => (
  <button
    onClick={onClick}
    className={`w-full flex items-center space-x-3 px-4 py-2.5 rounded-xl transition-all ${
      active 
        ? 'bg-blue-600 text-white shadow-md font-bold' 
        : 'text-slate-500 hover:bg-slate-100 font-medium'
    }`}
  >
    {icon}
    <span className="text-xs">{label}</span>
  </button>
);

const Card: React.FC<{ title: string; children: React.ReactNode; className?: string; action?: React.ReactNode }> = ({ title, children, className, action }) => (
  <div className={`bg-white p-6 rounded-2xl shadow-sm border border-slate-200 ${className}`}>
    <div className="flex justify-between items-center mb-6">
      <h3 className="text-base font-black text-slate-800 tracking-tight uppercase">{title}</h3>
      {action}
    </div>
    {children}
  </div>
);

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'Maj', 'Jun', 'Jul', 'Aug', 'Sep', 'Okt', 'Nov', 'Dec'];

type Tab = 'dashboard' | 'calendar' | 'standards' | 'stakeholders' | 'risks' | 'competence' | 'rondering' | 'objectives' | 'laws' | 'aspects' | 'templates' | 'incidents' | 'chat';

export default function App() {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [chapters, setChapters] = useState<ISOChapter[]>(ISO_CHAPTERS);
  const [selectedStandard, setSelectedStandard] = useState<ISOStandard>('9001');
  const [currentUser] = useState<User>({ name: 'Johan Kvalitetsson', email: 'johan@foretaget.se', role: 'admin', company: 'Innovationsbolaget AB' });

  // Processkarta State
  const [processMap, setProcessMap] = useState<ProcessMap>({
    management: [
      { id: 'm1', name: 'LEDNING & FÖRBÄTTRING', subProcesses: [], owner: 'Johan Kvalitetsson' }
    ],
    main: [
      { id: 'p1', name: 'MARKNAD', subProcesses: [], owner: 'Anna Marknad' },
      { id: 'p2', name: 'SÄLJ', subProcesses: [], owner: 'Sven Sälj' },
      { id: 'p3', name: 'PRODUKTION', subProcesses: [], owner: 'Johan Kvalitetsson' },
      { id: 'p4', name: 'PRODUKTUTVECKLING', subProcesses: [], owner: 'Erik Utveckling' }
    ],
    support: [
      { id: 's1', name: 'HR & LÖN', subProcesses: [], owner: 'Johan Kvalitetsson' },
      { id: 's2', name: 'IT', subProcesses: [], owner: 'IT-Teamet' },
      { id: 's3', name: 'INKÖP & LEVERANTÖRER', subProcesses: [], owner: 'Johan Kvalitetsson' },
      { id: 's4', name: 'EKONOMI', subProcesses: [], owner: 'Ekonomi-avd' },
      { id: 's5', name: 'MILJÖ & SÄKERHET', subProcesses: [], owner: 'Johan Kvalitetsson' }
    ]
  });

  const [selectedProcess, setSelectedProcess] = useState<{ category: keyof ProcessMap; id: string } | null>(null);

  // Mock data för personliga uppdrag och dokument
  const [myIncidents] = useState<Incident[]>([
    { id: 'inc1', type: 'deviation', title: 'Maskinhaveri linje 4', description: 'Givare trasig', date: '2024-05-10', reporter: 'Erik', responsible: 'Johan Kvalitetsson', status: 'investigating', deadline: '2024-05-20' },
    { id: 'inc2', type: 'improvement', title: 'Energibesparingsförslag', description: 'Byta till LED i hall B', date: '2024-05-12', reporter: 'Anna', responsible: 'Johan Kvalitetsson', status: 'open', deadline: '2024-06-01' }
  ]);

  const [myDocuments] = useState<LinkedDocument[]>([
    { id: 'doc1', name: 'Rutin för avvikelsehantering', type: 'rutin', status: 'godkänd', lastEdited: '2024-04-15', owner: 'Johan Kvalitetsson' },
    { id: 'doc2', name: 'Miljöpolicy 2024', type: 'process', status: 'utkast', lastEdited: '2024-05-01', owner: 'Johan Kvalitetsson' },
    { id: 'doc3', name: 'Utbildningsplan HR', type: 'bilaga', status: 'godkänd', lastEdited: '2024-03-20', owner: 'Johan Kvalitetsson' }
  ]);

  const [calendarEvents, setCalendarEvents] = useState<CalendarEvent[]>([]);
  const [messages, setMessages] = useState<Message[]>([{ id: '1', user: 'System', text: 'Välkommen till SafeQMS!', timestamp: '09:00' }]);
  const [isAiConsultant, setIsAiConsultant] = useState(false);
  const [aiPanel, setAiPanel] = useState({ isOpen: false, content: '', title: '' });
  const [isLoading, setIsLoading] = useState(false);

  const handleLogin = (e: React.FormEvent) => { e.preventDefault(); setIsLoggedIn(true); };

  const editProcessName = (category: keyof ProcessMap, id: string) => {
    const process = processMap[category].find(p => p.id === id);
    const newName = prompt('Ändra processnamn:', process?.name);
    if (newName && newName !== process?.name) {
      setProcessMap(prev => ({
        ...prev,
        [category]: prev[category].map(p => p.id === id ? { ...p, name: newName } : p)
      }));
    }
  };

  const addSubProcess = (category: keyof ProcessMap, id: string) => {
    const name = prompt('Ange namn på underprocess:');
    if (name) {
      setProcessMap(prev => ({
        ...prev,
        [category]: prev[category].map(p => {
          if (p.id === id) {
            return {
              ...p,
              subProcesses: [...(p.subProcesses || []), { id: Date.now().toString(), name }]
            };
          }
          return p;
        })
      }));
    }
  };

  const deleteSubProcess = (category: keyof ProcessMap, parentId: string, subId: string) => {
    if (!confirm('Vill du ta bort underprocessen?')) return;
    setProcessMap(prev => ({
      ...prev,
      [category]: prev[category].map(p => {
        if (p.id === parentId) {
          return {
            ...p,
            subProcesses: p.subProcesses?.filter(sp => sp.id !== subId)
          };
        }
        return p;
      })
    }));
  };

  const generatePlan = async () => {
    setIsLoading(true);
    const plan = await suggestAnnualPlan([selectedStandard]);
    if (plan) setCalendarEvents(plan.map((i: any) => ({ ...i, id: Math.random().toString(), completed: false })));
    setIsLoading(false);
  };

  const openAiAdvice = async (chapter: ISOChapter) => {
    setIsLoading(true);
    setAiPanel({ isOpen: true, title: `AI: K${chapter.number}`, content: 'Hämtar råd...' });
    const advice = await getISOAdvice(chapter.number, selectedStandard);
    setAiPanel({ isOpen: true, title: `AI-Expert: ${chapter.title}`, content: advice || 'Error.' });
    setIsLoading(false);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const input = form.message as HTMLInputElement;
    if (!input.value) return;
    const msg = { id: Date.now().toString(), user: currentUser.name, text: input.value, timestamp: 'Nu' };
    setMessages(prev => [...prev, msg]);
    const val = input.value;
    input.value = '';
    if (isAiConsultant) {
      setIsLoading(true);
      const res = await askISOConsultant(val, []);
      setMessages(prev => [...prev, { id: 'ai', user: 'ISO-AI Konsult', text: res || '...', timestamp: 'Nu' }]);
      setIsLoading(false);
    }
  };

  // Filtrera personliga ansvarsområden
  const myOwnedProcesses = useMemo(() => {
    const all = [...processMap.management, ...processMap.main, ...processMap.support];
    return all.filter(p => p.owner === currentUser.name);
  }, [processMap, currentUser.name]);

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 px-4">
        <div className="max-w-md w-full bg-white rounded-3xl shadow-2xl p-10 text-center">
            <div className="inline-flex p-4 bg-blue-100 text-blue-600 rounded-2xl mb-6"><CheckCircle2 size={40} /></div>
            <h1 className="text-3xl font-black text-slate-900 tracking-tighter mb-2">SafeQMS</h1>
            <p className="text-slate-500 mb-8 font-medium italic">Smartare Certifiering</p>
            <form onSubmit={handleLogin} className="space-y-4 text-left">
              <input type="email" required className="w-full px-5 py-3.5 border rounded-2xl outline-none focus:ring-2 focus:ring-blue-500" placeholder="E-post" />
              <input type="password" required className="w-full px-5 py-3.5 border rounded-2xl outline-none focus:ring-2 focus:ring-blue-500" placeholder="Lösenord" />
              <button type="submit" className="w-full bg-blue-600 text-white font-bold py-4 rounded-2xl hover:bg-blue-700 shadow-xl transition-all">Logga in</button>
            </form>
        </div>
      </div>
    );
  }

  const currentSelectedProc = selectedProcess 
    ? processMap[selectedProcess.category].find(p => p.id === selectedProcess.id) 
    : null;

  return (
    <div className="flex min-h-screen bg-slate-50">
      <aside className="w-64 bg-white border-r border-slate-200 p-6 flex flex-col hidden lg:flex">
        <div className="flex items-center space-x-2 mb-8 text-blue-600">
          <CheckCircle2 size={24} />
          <span className="text-xl font-black text-slate-900 tracking-tighter">SafeQMS</span>
        </div>
        <nav className="flex-1 space-y-0.5 overflow-y-auto pr-1">
          <SidebarItem icon={<LayoutDashboard size={16}/>} label="Översikt" active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} />
          <div className="pt-4 pb-1 px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Planering & Kontext</div>
          <SidebarItem icon={<CalendarIcon size={16}/>} label="Årshjul" active={activeTab === 'calendar'} onClick={() => setActiveTab('calendar')} />
          <SidebarItem icon={<Users size={16}/>} label="Intressenter" active={activeTab === 'stakeholders'} onClick={() => setActiveTab('stakeholders')} />
          <SidebarItem icon={<ShieldCheck size={16}/>} label="Riskhantering" active={activeTab === 'risks'} onClick={() => setActiveTab('risks')} />
          <div className="pt-4 pb-1 px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Utförande & Kontroll</div>
          <SidebarItem icon={<BookOpen size={16}/>} label="Standarder" active={activeTab === 'standards'} onClick={() => setActiveTab('standards')} />
          <SidebarItem icon={<ClipboardList size={16}/>} label="Rondering" active={activeTab === 'rondering'} onClick={() => setActiveTab('rondering')} />
          <SidebarItem icon={<GraduationCap size={16}/>} label="Kompetens" active={activeTab === 'competence'} onClick={() => setActiveTab('competence')} />
          <div className="pt-4 pb-1 px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Mätning & Förbättring</div>
          <SidebarItem icon={<Target size={16}/>} label="Mål & KPI" active={activeTab === 'objectives'} onClick={() => setActiveTab('objectives')} />
          <SidebarItem icon={<AlertTriangle size={16}/>} label="Ärenden" active={activeTab === 'incidents'} onClick={() => setActiveTab('incidents')} />
          <SidebarItem icon={<Gavel size={16}/>} label="Lagar & Krav" active={activeTab === 'laws'} onClick={() => setActiveTab('laws')} />
          <SidebarItem icon={<ShieldAlert size={16}/>} label="Aspekter" active={activeTab === 'aspects'} onClick={() => setActiveTab('aspects')} />
          <div className="pt-4 pb-1 px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Verktyg</div>
          <SidebarItem icon={<FileText size={16}/>} label="AI Mallar" active={activeTab === 'templates'} onClick={() => setActiveTab('templates')} />
          <SidebarItem icon={<MessageSquare size={16}/>} label="Chatt" active={activeTab === 'chat'} onClick={() => setActiveTab('chat')} />
        </nav>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto max-h-screen">
