              </div>
            </Card>
          </div>
        )}
      </main>

      {/* AI Panel Right */}
      <div className={`fixed inset-y-0 right-0 w-96 bg-white shadow-2xl transition-transform duration-300 z-50 border-l ${aiPanel.isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
