  const handleUpdatePassword = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordForm.new !== passwordForm.confirm) {
      alert('De nya lösenorden matchar inte varandra.');
      return;
    }
    alert('Lösenordet har uppdaterats framgångsrikt!');
    setPasswordForm({ current: '', new: '', confirm: '' });
  };

  const editProcessName = (category: keyof ProcessMap, id: string) => {
    const process = processMap[category].find(p => p.id === id);
    const newName = prompt('Ändra processnamn:', process?.name);
    if (newName && newName !== process?.name) {
      setProcessMap(prev => ({
        ...prev,
        [category]: prev[category].map(p => p.id === id ? { ...p, name: newName } : p)
      }));
    }
  };

  const addSubProcess = (category: keyof ProcessMap, id: string) => {
    const name = prompt('Ange namn på underprocess:');
    if (name) {
      setProcessMap(prev => ({
        ...prev,
        [category]: prev[category].map(p => {
          if (p.id === id) {
            return { ...p, subProcesses: [...(p.subProcesses || []), { id: Date.now().toString(), name }] };
          }
          return p;
        })
      }));
    }
  };

  const deleteSubProcess = (category: keyof ProcessMap, parentId: string, subId: string) => {
    if (!confirm('Vill du ta bort underprocessen?')) return;
    setProcessMap(prev => ({
      ...prev,
      [category]: prev[category].map(p => {
        if (p.id === parentId) {
          return { ...p, subProcesses: p.subProcesses?.filter(sp => sp.id !== subId) };
        }
        return p;
      })
    }));
  };

