                          className={`w-96 h-28 bg-yellow-400 hover:bg-yellow-500 text-slate-900 rounded-[2rem] shadow-xl flex flex-col items-center justify-center transition-all border-4 relative group active:scale-95 ${p.owner === currentUser.name ? 'border-blue-600 shadow-blue-100 ring-8 ring-blue-50/30' : 'border-yellow-300'}`}
