  const handleLogin = (e: React.FormEvent) => { e.preventDefault(); setIsLoggedIn(true); };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setCurrentUser(prev => ({ ...prev, profileImage: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProfile = () => {
    setCurrentUser(prev => ({
      ...prev,
      name: profileForm.name,
      title: profileForm.title,
      email: profileForm.email,
      phone: profileForm.phone
    }));
    alert('Dina uppgifter har sparats!');
  };

  const handleUpdatePassword = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordForm.new !== passwordForm.confirm) {
      alert('De nya lösenorden matchar inte varandra.');
      return;
    }
    alert('Lösenordet har uppdaterats framgångsrikt!');
    setPasswordForm({ current: '', new: '', confirm: '' });
  };

  const handleAddEvent = () => {
    if (!newEvent.title || !newEvent.date) return;
    const event: CalendarEvent = {
      id: Math.random().toString(36).substr(2, 9),
      title: newEvent.title,
      date: newEvent.date,
      startTime: newEvent.startTime,
      endTime: newEvent.endTime,
      type: newEvent.type as CalendarEventType,
      recurrence: newEvent.recurrence as RecurrenceType,
      completed: false,
      responsible: currentUser.name
    };
    setCalendarEvents([...calendarEvents, event]);
    setShowAddEventModal(false);
    setNewEvent({
      title: '',
      date: new Date().toISOString().split('T')[0],
      startTime: '09:00',
      endTime: '10:00',
      type: 'möte',
      recurrence: 'none'
    });
  };

  const editProcessName = (category: keyof ProcessMap, id: string) => {
    const process = processMap[category].find(p => p.id === id);
    const newName = prompt('Ändra processnamn:', process?.name);
    if (newName && newName !== process?.name) {
      setProcessMap(prev => ({
        ...prev,
        [category]: prev[category].map(p => p.id === id ? { ...p, name: newName } : p)
      }));
    }
  };

  const addSubProcess = (category: keyof ProcessMap, id: string) => {
    const name = prompt('Ange namn på underprocess:');
    if (name) {
      setProcessMap(prev => ({
        ...prev,
        [category]: prev[category].map(p => {
          if (p.id === id) {
            return { ...p, subProcesses: [...(p.subProcesses || []), { id: Date.now().toString(), name }] };
          }
          return p;
        })
      }));
    }
  };

  const deleteSubProcess = (category: keyof ProcessMap, parentId: string, subId: string) => {
    if (!confirm('Vill du ta bort underprocessen?')) return;
    setProcessMap(prev => ({
      ...prev,
      [category]: prev[category].map(p => {
        if (p.id === parentId) {
          return { ...p, subProcesses: p.subProcesses?.filter(sp => sp.id !== subId) };
        }
        return p;
      })
    }));
  };

  const generatePlan = async () => {
    setIsLoading(true);
    const plan = await suggestAnnualPlan([selectedStandard]);
    if (plan) {
      const now = new Date();
      const mapped = plan.map((i: any) => ({
        id: Math.random().toString(),
        title: i.title,
        date: new Date(now.getFullYear(), i.month, 15).toISOString().split('T')[0],
        startTime: '09:00',
        endTime: '10:00',
        type: i.type as CalendarEventType,
        completed: false,
        recurrence: 'none'
      }));
      setCalendarEvents([...calendarEvents, ...mapped]);
    }
    setIsLoading(false);
  };

  const openAiAdvice = async (chapter: ISOChapter) => {
    setIsLoading(true);
    setAiPanel({ isOpen: true, title: `AI: K${chapter.number}`, content: 'Hämtar råd...' });
