  hasDropdown?: boolean;
  isOpen?: boolean;
}> = ({ icon, label, active, onClick, hasDropdown, isOpen }) => (
  <button
    onClick={onClick}
    className={`w-full flex items-center justify-between px-4 py-2.5 rounded-xl transition-all ${
      active 
